/* Screens: auth, nav, render, dashboard, builder, release detail, settings, roster */
  function renderAuth(){ $('#app').innerHTML=`<main id="main-content" class="auth-shell auth-layout" tabindex="-1"><section class="auth-story" aria-label="Imposed Entertainment"><div class="auth-story-art" aria-hidden="true"></div><div class="auth-story-content"><div class="auth-logo auth-logo-large"><span><img src="/img/logo-512.png" alt=""></span><b>IMPOSED<br>ENTERTAINMENT</b></div><p class="auth-kicker">INDEPENDENT MUSIC. BUILT TOGETHER.</p><h2>Your music.<br><em>Your next chapter.</em></h2><p class="auth-story-copy">One place to submit releases, stay connected with the label, and follow every step from review to release day.</p><div class="auth-story-foot"><span class="auth-status-dot"></span> Artist &amp; label portal <span class="auth-foot-divider">/</span> Secure sign-in</div></div></section><section class="auth-panel"><div class="auth-card"><div class="auth-portal-switch" aria-label="Choose your portal"><a class="auth-portal-choice is-current" href="/signin" aria-current="page"><span class="auth-portal-icon">${icon('users',19)}</span><span class="auth-portal-copy"><strong>Artist &amp; label</strong><small>Secure workspace · invite required</small></span><span class="auth-portal-arrow">${icon('arrow',15)}</span></a><a class="auth-portal-choice listener-portal-choice" href="/listen"><span class="auth-portal-icon">${icon('headphones',19)}</span><span class="auth-portal-copy"><strong>Listener</strong><small>Discover artists · account optional</small></span><span class="auth-portal-arrow">${icon('arrow',15)}</span></a></div><div class="auth-logo auth-logo-compact"><span><img src="/img/logo-128.png" alt=""></span><b>IMPOSED<br>ENTERTAINMENT</b></div><p class="eyebrow blue">${authMode==='login'?'WELCOME BACK':'INVITE ONLY'}</p><h1>${authMode==='login'?'Sign in to your portal.':(invite&&invite.role==='label_admin'?'Join the label team.':'Accept your artist or label invite.')}</h1><p class="sub">${authMode==='login'?'Access your releases, updates and artist workspace.':'Use the email address that received your invitation.'}</p><p class="account-policy-note">This sign-in is exclusively for invited artists and label members. Listener discovery is separate; browse freely or create an optional listener account.</p>${authMode==='login'?`<div class="oauth-heading">Sign in with</div><div class="oauth-icon-row" aria-label="Social sign-in options"><button type="button" class="oauth-icon-btn oauth-google" data-action="google" aria-label="Continue with Google" title="Continue with Google"><svg viewBox="0 0 48 48" aria-hidden="true"><path fill="#EA4335" d="M24 9.5c3.54 0 6.71 1.22 9.21 3.6l6.85-6.85C35.9 2.38 30.47 0 24 0 14.62 0 6.51 5.38 2.56 13.22l7.98 6.19C12.43 13.72 17.74 9.5 24 9.5z"/><path fill="#4285F4" d="M46.98 24.55c0-1.57-.15-3.09-.38-4.55H24v9.02h12.94c-.58 2.96-2.26 5.48-4.78 7.18l7.73 6c4.51-4.18 7.09-10.36 7.09-17.65z"/><path fill="#FBBC05" d="M10.53 28.59c-.48-1.45-.76-2.99-.76-4.59s.27-3.14.76-4.59l-7.98-6.19C.92 16.46 0 20.12 0 24c0 3.88.92 7.54 2.56 10.78l7.97-6.19z"/><path fill="#34A853" d="M24 48c6.48 0 11.93-2.13 15.89-5.81l-7.73-6c-2.15 1.45-4.92 2.3-8.16 2.3-6.26 0-11.57-4.22-13.47-9.91l-7.98 6.19C6.51 42.62 14.62 48 24 48z"/></svg></button><button type="button" class="oauth-icon-btn oauth-x" data-action="oauth-x" aria-label="Continue with X" title="Continue with X"><span aria-hidden="true">𝕏</span></button><button type="button" class="oauth-icon-btn oauth-discord" data-action="oauth-discord" aria-label="Continue with Discord" title="Continue with Discord"><svg viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M19.7 5.2A18.4 18.4 0 0 0 15.2 3.8l-.6 1.2a16.8 16.8 0 0 0-5.2 0l-.6-1.2a18.4 18.4 0 0 0-4.5 1.4C1.5 9.4.7 13.5 1.1 17.6a18.5 18.5 0 0 0 5.5 2.8l1.2-2a11.8 11.8 0 0 1-1.9-.9l.5-.4a13.1 13.1 0 0 0 11.2 0l.5.4a11.8 11.8 0 0 1-1.9.9l1.2 2a18.5 18.5 0 0 0 5.5-2.8c.5-4.8-.8-8.9-3.2-12.4ZM8.7 14.6c-1.1 0-1.9-1-1.9-2.1s.8-2.1 1.9-2.1 1.9 1 1.9 2.1-.8 2.1-1.9 2.1Zm6.6 0c-1.1 0-1.9-1-1.9-2.1s.8-2.1 1.9-2.1 1.9 1 1.9 2.1-.8 2.1-1.9 2.1Z"/></svg></button></div>`:`<div class="auth-provider-note" role="note"><strong>Using Google?</strong><span>Google sign-in is for existing invited accounts. To accept a new invite, use your invited email and password first.</span></div>`}<div class="auth-divider"><span>${authMode==='login'?'or continue with email':'or create account with email'}</span></div><form id="auth-form">${authMode==='signup'?`<label class="field"><span>Invite code</span><input id="auth-invite" required placeholder="Paste your invite code" value="${esc(invite?invite.code:'')}" ${invite?'readonly':''}></label>`:''}<label class="field"><span>Email address</span><input id="auth-email" type="email" autocomplete="email" required ${authMode==='signup'&&invite?`value="${esc(invite.email)}" readonly`:''} placeholder="you@example.com"></label><div class="field"><label for="auth-password">Password</label><div class="password-input-wrap"><input id="auth-password" type="password" minlength="8" autocomplete="${authMode==='login'?'current-password':'new-password'}" required placeholder="${authMode==='login'?'Enter your password':'At least 8 characters'}"><button type="button" class="password-reveal" data-action="toggle-password" aria-label="Show password" aria-pressed="false">${icon('eye',17)}<span>Show</span></button></div></div>${authMode==='signup'?`<div class="field"><label for="auth-confirm-password">Confirm password</label><div class="password-input-wrap"><input id="auth-confirm-password" type="password" minlength="8" autocomplete="new-password" required placeholder="Re-enter your password"><button type="button" class="password-reveal" data-action="toggle-password" aria-label="Show confirmation password" aria-pressed="false">${icon('eye',17)}<span>Show</span></button></div></div>`:''}<div id="cf-turnstile" class="cf-box" aria-label="Cloudflare security verification"></div><p id="captcha-status" class="captcha-status" role="status" aria-live="polite">Loading security check…</p><button class="primary full auth-submit" type="submit">${authMode==='login'?'Sign in securely':'Create account'} ${icon('arrow',16)}</button></form><button class="link-button auth-toggle" data-action="auth-toggle">${authMode==='login'?'Have an artist or label invite? Accept invite':'Already have an account? Sign in'}</button>${authMode==='login'?`<div class="auth-divider auth-divider-small"><span>or</span></div><button class="secondary full magic-button" data-action="magic">${icon('mail',16)} Email me a sign-in link</button>`:''}<p class="legal">Your account and release information are protected by secure authentication.</p>${authMode==='login'?`<div class="guest-entry"><span class="guest-entry-line"></span><small>No account needed. Complete a quick Cloudflare security check to browse public artists.</small></div>`:''}</div><p class="auth-panel-footer">© ${new Date().getFullYear()} Imposed Entertainment</p><nav class="auth-legal-links" aria-label="Legal"><a href="/privacy">Privacy Policy</a><span aria-hidden="true">·</span><a href="/terms">Terms of Service</a></nav></section></main>`; bind(); }


  function renderListenerAccount(){
    if(session?.user?.user_metadata?.account_type==='listener'){
      $('#app').innerHTML=`<main id="main-content" class="auth-shell listener-account-shell" tabindex="-1"><section class="auth-panel"><div class="auth-card"><div class="auth-logo auth-logo-compact"><span><img src="/img/logo-128.png" alt=""></span><b>IMPOSED<br>ENTERTAINMENT</b></div><p class="eyebrow blue">LISTENER ACCOUNT</p><h1>You're all set.</h1><p class="sub">You're signed in as ${esc(session.user.email||'a listener')}. Your listener account is separate from the invite-only artist and label workspace.</p><a class="primary full" href="/listen">Discover artists ${icon('arrow',16)}</a><section class="listener-account-library" aria-labelledby="listener-library-title"><div class="section-head"><div><p class="eyebrow blue">YOUR MUSIC</p><h2 id="listener-library-title">Your library</h2><p class="sub">Saved artists and releases follow you when you sign in on another device.</p></div><button type="button" class="secondary" id="listener-library-refresh">Refresh</button></div><div id="listener-library-status" class="muted" role="status" aria-live="polite">Loading your saved music…</div><div id="listener-library-items" class="listener-library-items"></div></section><section class="listener-recent-section" aria-labelledby="listener-recent-title"><div class="section-head"><div><p class="eyebrow blue">PICK UP WHERE YOU LEFT OFF</p><h2 id="listener-recent-title">Recently explored</h2><p class="sub">Your latest artist pages on this device, ready to revisit.</p></div><button type="button" class="secondary" id="listener-recent-clear">Clear history</button></div><div id="listener-recent-items" class="listener-recent-items"></div></section><section class="listener-following-section" aria-labelledby="listener-following-title"><div class="section-head"><div><p class="eyebrow blue">STAY IN THE LOOP</p><h2 id="listener-following-title">Artists you follow</h2><p class="sub">Follow artists to get notified when they release new music.</p></div><button type="button" class="secondary" id="listener-following-refresh">Refresh</button></div><div id="listener-following-status" class="muted" role="status" aria-live="polite">Loading followed artists…</div><div id="listener-following-items" class="listener-following-items"></div></section><section class="listener-notifications-section" aria-labelledby="listener-notifications-title"><div class="section-head"><div><p class="eyebrow blue">NEW FROM YOUR ARTISTS</p><h2 id="listener-notifications-title">Release notifications</h2><p class="sub">Updates from artists you follow appear here.</p></div><button type="button" class="secondary" id="listener-notifications-refresh">Refresh</button></div><label class="listener-notification-preference"><span><strong>New release alerts</strong><small>Notify me when followed artists publish music.</small></span><input type="checkbox" id="listener-release-notification-toggle" checked></label><div id="listener-notifications-status" class="muted" role="status" aria-live="polite">Checking for updates…</div><div id="listener-notifications-items" class="listener-notifications-items"></div></section><button type="button" class="secondary full" data-action="listener-signout">Sign out</button></div><nav class="auth-legal-links" aria-label="Legal"><a href="/privacy">Privacy Policy</a><span aria-hidden="true">·</span><a href="/terms">Terms of Service</a></nav></section></main>`;
      bind();loadListenerLibrary();loadListenerRecent();loadListenerFollowing();loadListenerNotifications();loadListenerNotificationPreference();$('#listener-release-notification-toggle')?.addEventListener('change',saveListenerNotificationPreference);$('#listener-library-refresh')?.addEventListener('click',loadListenerLibrary);$('#listener-recent-clear')?.addEventListener('click',clearListenerRecent);$('#listener-following-refresh')?.addEventListener('click',loadListenerFollowing);$('#listener-notifications-refresh')?.addEventListener('click',loadListenerNotifications);return;
    }
    window.__ieListenerAuthMode=window.__ieListenerAuthMode==='signup'?'signup':'login';
    authMode=window.__ieListenerAuthMode;
    $('#app').innerHTML=`<main id="main-content" class="auth-shell listener-account-shell" tabindex="-1"><section class="auth-panel"><div class="auth-card"><div class="auth-portal-switch" aria-label="Choose your portal"><a class="auth-portal-choice" href="/signin"><span class="auth-portal-icon">${icon('users',19)}</span><span class="auth-portal-copy"><strong>Artist &amp; label</strong><small>Invite required</small></span><span class="auth-portal-arrow">${icon('arrow',15)}</span></a><a class="auth-portal-choice listener-portal-choice is-current" href="/listen"><span class="auth-portal-icon">${icon('headphones',19)}</span><span class="auth-portal-copy"><strong>Listener</strong><small>Discover music and follow artists</small></span><span class="auth-portal-arrow">${icon('arrow',15)}</span></a></div><div class="auth-logo auth-logo-compact"><span><img src="/img/logo-128.png" alt=""></span><b>IMPOSED<br>ENTERTAINMENT</b></div><p class="eyebrow blue">${authMode==='login'?'LISTENER SIGN IN':'FREE LISTENER ACCOUNT'}</p><h1>${authMode==='login'?'Welcome back.':'Make listening personal.'}</h1><p class="sub">${authMode==='login'?'Sign in to your listener account.':'Create an account to make your listener experience yours. No artist invite needed.'}</p><form id="auth-form"><label class="field"><span>Email address</span><input id="auth-email" type="email" autocomplete="email" required placeholder="you@example.com"></label><div class="field"><label for="auth-password">Password</label><div class="password-input-wrap"><input id="auth-password" type="password" minlength="8" autocomplete="${authMode==='login'?'current-password':'new-password'}" required placeholder="${authMode==='login'?'Enter your password':'At least 8 characters'}"><button type="button" class="password-reveal" data-action="toggle-password" aria-label="Show password" aria-pressed="false">${icon('eye',17)}<span>Show</span></button></div></div>${authMode==='signup'?'<div class="field"><label for="auth-confirm-password">Confirm password</label><div class="password-input-wrap"><input id="auth-confirm-password" type="password" minlength="8" autocomplete="new-password" required placeholder="Re-enter your password"><button type="button" class="password-reveal" data-action="toggle-password" aria-label="Show confirmation password" aria-pressed="false">&#128065;<span>Show</span></button></div></div>':''}<div id="cf-turnstile" class="cf-box" aria-label="Cloudflare security verification"></div><p id="captcha-status" class="captcha-status" role="status" aria-live="polite">Loading security check…</p><button class="primary full auth-submit" type="submit">${authMode==='login'?'Sign in':'Create listener account'} ${icon('arrow',16)}</button></form><button type="button" class="link-button auth-toggle" data-action="auth-toggle">${authMode==='login'?'New here? Create a listener account':'Already have a listener account? Sign in'}</button><p class="account-policy-note">Listener accounts cannot access artist tools or label data. Artist and label accounts remain invite-only.</p><p class="legal">By continuing, you agree to our <a href="/terms">Terms</a> and <a href="/privacy">Privacy Policy</a>.</p></div><nav class="auth-legal-links" aria-label="Legal"><a href="/privacy">Privacy Policy</a><span aria-hidden="true">·</span><a href="/terms">Terms of Service</a></nav></section></main>`;
    bind();
  }


  async function loadListenerFollowing(){
    const status=$('#listener-following-status'),root=$('#listener-following-items');if(!status||!root)return;
    status.textContent='Loading followed artists…';root.innerHTML='';
    try{
      const userId=session?.user?.id;if(!userId)throw new Error('Sign in again to view followed artists.');
      const {data,error}=await sb.from('listener_artist_follows').select('id,artist_slug,artist_name,created_at').eq('user_id',userId).order('created_at',{ascending:false}).limit(200);if(error)throw error;
      const rows=Array.isArray(data)?data:[];
      if(!rows.length){status.textContent='You’re not following anyone yet. Open an artist page and choose Follow artist to start getting release updates.';return;}
      status.textContent=rows.length+' followed '+(rows.length===1?'artist':'artists');
      root.innerHTML=rows.map(x=>'<article class="listener-following-item"><a href="/listen/artist/'+encodeURIComponent(x.artist_slug)+'"><span class="listener-following-art" aria-hidden="true">♫</span><span class="listener-following-copy"><strong>'+esc(x.artist_name||'Independent artist')+'</strong><small>New release notifications enabled</small></span></a><button type="button" class="secondary" data-unfollow="'+esc(x.id)+'" aria-label="Unfollow '+esc(x.artist_name||'artist')+'">Following ✓</button></article>').join('');
      root.querySelectorAll('[data-unfollow]').forEach(btn=>btn.onclick=async()=>{btn.disabled=true;try{const {error}=await sb.from('listener_artist_follows').delete().eq('id',btn.dataset.unfollow).eq('user_id',userId);if(error)throw error;await loadListenerFollowing();toast('Artist unfollowed.','success');}catch(e){toast(e.message||'Could not unfollow artist.','error');btn.disabled=false;}});
    }catch(e){status.textContent=e.message||'Followed artists could not load.';}
  }

  async function loadListenerNotificationPreference(){
    const input=$('#listener-release-notification-toggle');if(!input)return;
    try{const {data,error}=await sb.from('profiles').select('notification_preferences').eq('id',session.user.id).maybeSingle();if(error)throw error;input.checked=(data?.notification_preferences?.new_followed_releases)!==false;}
    catch(e){input.checked=true;input.title='Preference could not be loaded; the default is enabled.';}
  }
  async function saveListenerNotificationPreference(){
    const input=$('#listener-release-notification-toggle');if(!input)return;
    input.disabled=true;
    try{const {data,error:readError}=await sb.from('profiles').select('notification_preferences').eq('id',session.user.id).maybeSingle();if(readError)throw readError;const prefs={...(data?.notification_preferences||{}),new_followed_releases:input.checked};const {error}=await sb.from('profiles').update({notification_preferences:prefs}).eq('id',session.user.id);if(error)throw error;toast(input.checked?'New release notifications enabled.':'New release notifications paused.','success');}
    catch(e){input.checked=!input.checked;toast(e.message||'Could not save notification preference.','error');}
    finally{input.disabled=false;}
  }

  async function loadListenerNotifications(){
    const status=$('#listener-notifications-status'),root=$('#listener-notifications-items');if(!status||!root)return;
    status.textContent='Checking for release updates…';root.innerHTML='';
    try{
      const userId=session?.user?.id;if(!userId)throw new Error('Sign in again to view notifications.');
      const {data,error}=await sb.from('notifications').select('id,kind,title,body,release_id,artist_slug,read,created_at').eq('user_id',userId).eq('kind','followed_artist_release').order('created_at',{ascending:false}).limit(30);if(error)throw error;
      const rows=Array.isArray(data)?data:[];
      if(!rows.length){status.textContent='No new release updates yet. When an artist you follow releases music, it will show up here.';return;}
      status.textContent=rows.filter(x=>!x.read).length+' unread · '+rows.length+' recent update'+(rows.length===1?'':'s');
      root.innerHTML=rows.map(x=>'<article class="listener-notification-item '+(x.read?'is-read':'is-unread')+'"><span class="listener-notification-icon" aria-hidden="true">♫</span><div><strong>'+esc(x.title||'New music from an artist you follow')+'</strong><p>'+esc(x.body||'A followed artist has released new music.')+'</p><small>'+esc(x.created_at?new Date(x.created_at).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'}):'Recently')+'</small></div>'+(x.artist_slug?'<a class="secondary" href="/listen/artist/'+encodeURIComponent(x.artist_slug)+'#release-'+encodeURIComponent(x.release_id||'')+'">View artist</a>':'')+(!x.read?'<button type="button" class="secondary" data-notification-read="'+esc(x.id)+'">Mark read</button>':'<span class="listener-notification-read-label">Read</span>')+'</article>').join('');
      root.querySelectorAll('[data-notification-read]').forEach(btn=>btn.onclick=async()=>{btn.disabled=true;try{const {error}=await sb.from('notifications').update({read:true}).eq('id',btn.dataset.notificationRead).eq('user_id',userId);if(error)throw error;await loadListenerNotifications();}catch(e){toast(e.message||'Could not mark notification as read.','error');btn.disabled=false;}});
    }catch(e){status.textContent=e.message||'Release notifications could not load.';}
  }


  function loadListenerRecent(){
    const root=$('#listener-recent-items');if(!root)return;
    let recent=[];try{recent=JSON.parse(localStorage.getItem('ie_recent_artists_v1')||'[]').filter(x=>x&&typeof x.slug==='string'&&/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(x.slug)).slice(0,8);}catch(_){}
    if(!recent.length){root.innerHTML='<div class="listener-recent-empty"><strong>Your next discovery is waiting.</strong><p>Browse the roster and open an artist page. It will appear here for quick access on this device.</p><a class="secondary" href="/listen">Explore artists ↗</a></div>';return;}
    root.innerHTML=recent.map(item=>'<a class="listener-recent-item" href="/listen/artist/'+encodeURIComponent(item.slug)+'"><span class="listener-recent-art" aria-hidden="true">♫</span><span><strong>'+esc(item.name||'Independent artist')+'</strong><small>'+esc(item.at?new Date(item.at).toLocaleDateString(undefined,{month:'short',day:'numeric'}):'Recently viewed')+'</small></span><span class="listener-recent-arrow" aria-hidden="true">↗</span></a>').join('');
  }
  function clearListenerRecent(){try{localStorage.removeItem('ie_recent_artists_v1');}catch(_){}loadListenerRecent();toast('Recently explored history cleared','success');}

  async function loadListenerLibrary(){
    const status=$('#listener-library-status'),items=$('#listener-library-items');if(!status||!items)return;
    status.textContent='Loading your saved music…';items.innerHTML='';
    try{
      const userId=session?.user?.id;if(!userId)throw new Error('Sign in again to load your library.');
      let localArtists=[];try{localArtists=JSON.parse(localStorage.getItem('ie_saved_artists_v1')||'[]').filter(x=>typeof x==='string'&&/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(x)).slice(0,200);}catch(_){}
      if(localArtists.length){const rows=localArtists.map(slug=>({user_id:userId,item_type:'artist',item_key:slug,artist_slug:slug,title:'',artist_name:''}));const migrated=await sb.from('listener_library').upsert(rows,{onConflict:'user_id,item_type,item_key',ignoreDuplicates:true});if(migrated.error)console.warn('Local listener saves could not be synced',migrated.error.message);}
      const {data,error}=await sb.from('listener_library').select('id,item_type,item_key,artist_slug,release_id,title,artist_name,created_at').eq('user_id',userId).order('created_at',{ascending:false}).limit(400);if(error)throw error;
      const rows=Array.isArray(data)?data:[];
      if(!rows.length){status.textContent='Your library is ready. Save an artist or release while browsing to build your collection.';return;}
      status.textContent=rows.length+' saved '+(rows.length===1?'item':'items');
      items.innerHTML=rows.map(row=>{const artist=row.item_type==='artist',href=artist?'/listen/artist/'+encodeURIComponent(row.artist_slug||row.item_key):'/listen/artist/'+encodeURIComponent(row.artist_slug||'')+'#release-'+encodeURIComponent(row.release_id||row.item_key);const title=artist?(row.title||row.artist_name||row.artist_slug||'Saved artist'):(row.title||'Saved release');const subtitle=artist?'Artist':(row.artist_name||'Independent artist')+' · Release';return '<article class="listener-library-item"><span class="listener-library-icon" aria-hidden="true">'+(artist?'♫':'◉')+'</span><div class="listener-library-copy"><strong>'+esc(title)+'</strong><small>'+esc(subtitle)+'</small></div><a class="secondary" href="'+esc(href)+'">Open ↗</a><button type="button" class="secondary" data-library-remove="'+esc(row.id)+'" aria-label="Remove '+esc(title)+' from your library">Remove</button></article>';}).join('');
      items.querySelectorAll('[data-library-remove]').forEach(btn=>btn.onclick=async()=>{btn.disabled=true;try{const {error}=await sb.from('listener_library').delete().eq('id',btn.dataset.libraryRemove).eq('user_id',userId);if(error)throw error;await loadListenerLibrary();}catch(e){toast(e.message||'Could not remove item','error');btn.disabled=false;}});
    }catch(e){status.textContent=e.message||'Your library could not load.';}
  }

  function sidebarCollapsed(){try{return localStorage.getItem('ie-sidebar-collapsed')==='1';}catch(_){return false;}}
  function nav(){return `<header class="nav"><div class="nav-inner"><button class="brand" data-action="dashboard"><span class="brand-mark"><img src="/img/logo-128.png" alt="Imposed Entertainment"></span><span class="brand-wordmark">IMPOSED <b>ENTERTAINMENT</b></span></button><button class="sidebar-collapse-toggle" data-action="sidebar-toggle" aria-label="${sidebarCollapsed()?'Expand sidebar':'Collapse sidebar'}" title="${sidebarCollapsed()?'Expand sidebar':'Collapse sidebar'}">${icon(sidebarCollapsed()?'panel-left-open':'panel-left-close',17)}</button><div class="sidebar-label">YOUR WORKSPACE</div><div class="desktop-nav"><button class="nav-link ${view==='dashboard'?'active':''}" data-action="dashboard">${icon('home',17)} <span>Overview</span></button><div class="nav-group-label">MUSIC &amp; RELEASES</div><button class="nav-link ${view==='discography'?'active':''}" data-action="discography">${icon('disc',17)} <span>Discography</span></button><button class="nav-link ${view==='podcasts'?'active':''}" data-action="podcasts">${icon('mic-vocal',17)} <span>Podcast studio</span></button><button class="nav-link ${view==='pipeline'?'active':''}" data-action="pipeline">${icon('workflow',17)} <span>Release pipeline</span></button>${isAdmin()?"":`<button class="nav-link ${view==='studio'?'active':''}" data-action="studio">${icon('sparkles',17)} <span>Artist studio</span></button>`}<button class="nav-link ${view==='vault'?'active':''}" data-action="vault">${icon('file',17)} <span>File vault</span></button><button class="nav-link ${view==='business'?'active':''}" data-action="business">${icon('briefcase-business',17)} <span>Business suite</span></button><button class="nav-link ${view==='calendar'?'active':''}" data-action="calendar">${icon('calendar',17)} <span>Release calendar</span></button><button class="nav-link ${view==='insights'?'active':''}" data-action="insights">${icon('chart-no-axes-combined',17)} <span>Insights</span></button>${isAdmin()?'':`<button class="new-btn" data-action="new">${icon('plus',17)} <span>New release</span></button>`}<div class="nav-group-label">PEOPLE &amp; WORKSPACE</div><button class="nav-link ${view==='activity'?'active':''}" data-action="activity">${icon('check-square',17)} <span>Tasks & activity</span></button><button class="nav-link ${view==='notifications'?'active':''}" data-action="notifications">${icon('bell',17)} <span>Notifications</span>${unreadVisibleCount()>0?`<b class="dot">${unreadVisibleCount()}</b>`:''}</button><button class="nav-link ${view==='bands'?'active':''}" data-action="bands">${icon('users',17)} <span>Bands</span>${myBandInvites.length?`<b class="dot">${myBandInvites.length}</b>`:''}</button><button class="nav-link ${view==='discover'||view==='profile'?'active':''}" data-pf="discover">${icon('compass',17)} <span>Discover artists</span></button><div class="nav-group-label">FINANCE &amp; ADMIN</div><button class="nav-link ${view==='earnings'?'active':''}" data-action="earnings"><b class="gbp">£</b> <span>Earnings</span></button><button class="nav-link ${view==='statements'?'active':''}" data-action="statements">${icon('file',17)} <span>Statements</span></button>${isAdmin()?`<button class="nav-link ${view==='operations'?'active':''}" data-action="operations">${icon('settings',17)} <span>Operations centre</span></button><button class="nav-link ${view==='roster'?'active':''}" data-action="roster">${icon('users',17)} <span>Roster & invites</span></button>`:''}</div><div class="sidebar-bottom"><div class="sidebar-label">ACCOUNT</div><div class="utility-row"><button class="icon-btn ie-quickjump-trigger" type="button" data-ie-quicknav-open aria-label="Quick navigation" title="Quick navigation (Ctrl / ⌘ K)">${icon('command',17)}<span>Quick jump</span><kbd>Ctrl K</kbd></button><button class="icon-btn" data-action="search" title="Search">${icon('search',17)}<span>Search</span></button>${isAdmin()?"":`<button class="icon-btn ${view==='support'?'active':''}" data-action="support">${icon('mail',17)}<span>Help & support</span></button>`}<button class="icon-btn ${view==='settings'?'active':''}" data-action="settings">${icon('settings',17)}<span>Settings & preferences</span></button></div><div class="sidebar-profile"><button class="avatar" ${isAdmin()?'data-action="settings" title="Account settings" aria-label="Open account settings"':'data-pf="my-page" title="My public page" aria-label="Open my profile"'}>${profile.avatar_path?`<img src="${esc(MEDIA_URL(profile.avatar_path))}" alt="">`:esc((profile.display_name||profile.email||'IE').slice(0,2).toUpperCase())}</button><div class="sidebar-profile-copy"><strong>${esc(profile.display_name||profile.email||'Account')}</strong><small>${isAdmin()?'Label team':'Artist workspace'}</small></div><button class="icon-btn sidebar-language-shortcut" type="button" data-action="settings" aria-label="Language and settings" title="Language and settings">${icon('globe',15)}<span>Language</span></button></div><nav class="sidebar-legal-links" aria-label="Legal"><a href="/privacy">Privacy</a><span aria-hidden="true">·</span><a href="/terms">Terms</a></nav></div><button class="mobile-menu icon-btn" data-action="mobile" aria-label="${mobile?'Close navigation':'Open navigation'}" aria-expanded="${mobile?'true':'false'}" aria-controls="mobile-navigation-menu" title="${mobile?'Close menu':'Open menu'}">${icon(mobile?'x':'menu',21)}</button></div>${mobile?`<nav class="mobile-nav" id="mobile-navigation-menu" aria-label="Mobile navigation"><div class="mobile-nav-label">WORKSPACE</div><button type="button" data-ie-quicknav-open title="Quick navigation (Ctrl / ⌘ K)">${icon('command',17)} Quick jump <kbd>Ctrl / ⌘ K</kbd></button><button data-action="dashboard">${icon('home',17)} Overview</button><div class="mobile-nav-label">MUSIC &amp; RELEASES</div><button data-action="discography">${icon('disc',17)} Discography</button><button data-action="podcasts">${icon('mic-vocal',17)} Podcast studio</button><button data-action="pipeline">${icon('workflow',17)} Release pipeline</button>${isAdmin()?'':`<button data-action="studio">${icon('sparkles',17)} Artist studio</button>`}<button data-action="vault">${icon('file',17)} File vault</button><button data-action="business">${icon('briefcase-business',17)} Business suite</button><button data-action="calendar">${icon('calendar',17)} Release calendar</button><button data-action="insights">${icon('chart-no-axes-combined',17)} Insights</button>${isAdmin()?'':`<button data-action="new">${icon('plus',17)} New release</button>`}<div class="mobile-nav-label">PEOPLE &amp; WORKSPACE</div><button data-action="activity">${icon('check-square',17)} Tasks & activity</button><button data-action="notifications">${icon('bell',17)} Notifications${unreadVisibleCount()>0?` (${unreadVisibleCount()})`:''}</button><button data-action="bands">${icon('users',17)} Bands${myBandInvites.length?` (${myBandInvites.length})`:''}</button><button data-pf="discover">${icon('compass',17)} Discover artists</button><div class="mobile-nav-label">FINANCE &amp; ADMIN</div><button data-action="earnings"><b class="gbp">£</b> Earnings</button><button data-action="statements">${icon('file',17)} Statements</button>${isAdmin()?`<button data-action="operations">${icon('settings',17)} Operations centre</button><button data-action="roster">${icon('users',17)} Roster & invites</button>`:''}<div class="mobile-nav-label">ACCOUNT</div>${isAdmin()?`<button data-action="settings">${icon('settings',17)} Account settings</button>`:`<button data-pf="my-page">${icon('users',17)} My public profile</button>`}<button data-action="search">${icon('search',17)} Search</button>${isAdmin()?"":`<button data-action="support">${icon('mail',17)} Help & support</button>`}<button data-action="settings">${icon('settings',17)} Settings & preferences</button><button data-action="logout">${icon('logout',17)} Sign out</button><div class="mobile-legal-links"><a href="/privacy">Privacy Policy</a><a href="/terms">Terms of Service</a></div></nav>`:''}</header>`;}
  function workspaceBannerMarkup(){const a=getAppearancePreferences();if(a.bannerEnabled!==true||(!a.banner&&!/^#[0-9a-f]{6}$/i.test(String(a.bannerColor||''))))return '';return `<div class="ie-banner" aria-hidden="true" style="${a.banner?`background-image:linear-gradient(180deg,rgba(8,10,15,.08),rgba(8,10,15,.68)),url('${a.banner}')`:''}${a.bannerColor?`;--ie-banner-color:${esc(a.bannerColor)}`:''}"></div>`;}
  function workspaceTopbar(){const labels={dashboard:'Overview',podcasts:'Podcast studio',builder:'New release',release:'Release details',settings:'Settings',support:'Help & support',earnings:'Earnings',statements:'Statements',operations:'Operations centre',notifications:'Notifications',bands:'Bands',roster:'Roster & invites',discover:'Discover artists',discography:'Discography',calendar:'Release calendar',insights:'Insights',pipeline:'Release pipeline',studio:'Artist studio',vault:'File vault',activity:'Tasks & activity',profile:'Artist profile',editprofile:'Edit profile'};return `<header class="workspace-topbar"><div class="topbar-location"><span>IMPOSED ENTERTAINMENT</span><b>${labels[view]||'Workspace'}</b></div><div class="topbar-tools"><button class="topbar-search" data-action="search" aria-label="Search pages, releases, bands and artists">${icon('search',16)}<span>Search anything…</span><kbd>⌘ K</kbd></button><button class="topbar-account" ${isAdmin()?'data-action="settings" aria-label="Open account settings"':'data-pf="my-page" aria-label="Open your public profile"'}>${profile.avatar_path?`<img src="${esc(MEDIA_URL(profile.avatar_path))}" alt="">`:esc((profile.display_name||profile.email||'IE').slice(0,2).toUpperCase())}</button></div></header>`;}
  function enhanceNavigation(){
    const groups=[['.desktop-nav','.nav-group-label'],['.mobile-nav','.mobile-nav-label']];
    groups.forEach(([containerSelector,labelSelector])=>{
      const container=document.querySelector(containerSelector);if(!container||container.dataset.grouped==='1')return;
      const isMobile=containerSelector==='.mobile-nav';
      const children=Array.from(container.children);let group=null;
      children.forEach(node=>{
        if(node.matches(labelSelector)){
          const label=(node.textContent||'').trim();
          group=document.createElement('details');group.className='nav-accordion';
          group.dataset.navGroup=label.toLowerCase().replace(/[^a-z0-9]+/g,'-');
          const summary=document.createElement('summary');summary.className='nav-accordion-title';summary.textContent=label;
          group.appendChild(summary);container.insertBefore(group,node);node.remove();
          // The mobile dropdown starts compact; only the group containing the current page opens.
          // Desktop keeps its familiar expanded workspace/release sections.
          group.open=!isMobile&&(label.toLowerCase().includes('release')||label.toLowerCase()==='workspace'||label.toLowerCase().includes('workspace & community')||label.toLowerCase()==='account');
          return;
        }
        if(group){
          group.appendChild(node);
          const action=node.dataset?.action;
          const pf=node.dataset?.pf;
          const active=action===view||((view==='discover'||view==='profile')&&pf==='discover')||(view==='editprofile'&&pf==='my-page');
          if(active){node.classList.add('active');node.setAttribute('aria-current','page');group.open=true;}
        }
      });
      if(isMobile){
        // Keep the page scrollable even while the mobile menu is open. The menu has its own
        // contained scroll area, so it must not lock the document or trap touch scrolling.
        document.body.style.overflow='';
        document.body.style.overflowY='auto';
        document.documentElement.style.overflowY='auto';
        const navHeader=document.querySelector('.shell > .nav');
        const navBottom=navHeader?.getBoundingClientRect().bottom||120;
        container.style.setProperty('--mobile-nav-top',Math.max(80,Math.round(navBottom))+'px');
        container.addEventListener('click',event=>{
          const summary=event.target.closest?.('.nav-accordion-title');
          if(!summary)return;
          const selected=summary.parentElement;
          if(!selected?.classList.contains('nav-accordion'))return;
          // Only one group may expand at a time, preventing a very long menu.
          if(!selected.open)container.querySelectorAll('.nav-accordion[open]').forEach(section=>{if(section!==selected)section.open=false;});
        });
        const activeGroup=container.querySelector('.nav-accordion .active')?.closest('.nav-accordion');
        container.querySelectorAll('.nav-accordion').forEach(section=>{section.open=section===activeGroup;});
        const searchWrap=document.createElement('label');searchWrap.className='mobile-nav-search';
        searchWrap.innerHTML='<span class="sr-only">Filter navigation</span><input type="search" id="mobile-nav-filter" autocomplete="off" placeholder="Find a page…" aria-label="Filter navigation links"><span class="mobile-nav-search-hint" aria-hidden="true">⌕</span>';
        container.prepend(searchWrap);
        const filterInput=searchWrap.querySelector('input');
        filterInput.addEventListener('input',()=>{
          const query=filterInput.value.trim().toLocaleLowerCase();let total=0;
          container.querySelectorAll('.nav-accordion').forEach(section=>{
            let matches=0;
            section.querySelectorAll(':scope > button').forEach(link=>{
              const show=!query||(link.textContent||'').toLocaleLowerCase().includes(query);
              link.hidden=!show;if(show)matches++;
            });
            section.hidden=!!query&&matches===0;section.open=!!query?matches>0:section===container.querySelector('.nav-accordion .active')?.closest('.nav-accordion');total+=matches;
          });
          let empty=container.querySelector('.mobile-nav-no-results');
          if(query&&total===0){if(!empty){empty=document.createElement('p');empty.className='mobile-nav-no-results';empty.textContent='No pages match that search.';container.appendChild(empty);}}
          else empty?.remove();
        });
      }
      container.dataset.grouped='1';
    });
  }

  function closeMobileMenu(){
    if(!mobile)return;
    mobile=false;
    document.body.style.overflow='';
    document.body.style.overflowY='auto';
    document.documentElement.style.overflowY='auto';
    document.getElementById('mobile-navigation-menu')?.remove();
    const button=document.querySelector('.shell .mobile-menu');
    if(button){button.setAttribute('aria-expanded','false');button.setAttribute('aria-label','Open navigation');button.title='Open menu';button.innerHTML=icon('menu',21);}
  }
  function setupMobileMenuDismiss(){
    if(document.documentElement.dataset.mobileMenuDismissBound==='1')return;
    document.documentElement.dataset.mobileMenuDismissBound='1';
    document.addEventListener('click',event=>{
      if(!mobile)return;
      // The menu trigger re-renders the app synchronously. That detaches the original
      // clicked button before this document-level listener runs, so checking only
      // nav.contains(event.target) incorrectly treats the opening click as outside.
      // Use the original event path to recognise the trigger even after re-render.
      const path=typeof event.composedPath==='function'?event.composedPath():[];
      if(path.some(node=>node instanceof Element && (node.matches('.mobile-menu')||node.matches('.mobile-nav-close'))))return;
      const shell=document.querySelector('.shell');
      const nav=shell?.querySelector('.nav');
      if(nav&&(nav.contains(event.target)||path.includes(nav)||path.some(node=>node instanceof Element&&node.closest?.('.nav'))))return;
      closeMobileMenu();
    });
    document.addEventListener('keydown',event=>{
      if(event.key!=='Escape'||!mobile)return;
      closeMobileMenu();document.querySelector('.mobile-menu')?.focus();
    });
  }
  setupMobileMenuDismiss();
  function workspaceDataWarningMarkup(){
    const messages=Object.values(workspaceDataWarnings||{});
    if(!messages.length)return '';
    return `<aside class="workspace-data-warning" role="status" aria-live="polite"><div><strong>Some workspace data didn't load</strong><p>${messages.map(esc).join(' ')}</p></div><button type="button" class="secondary" data-action="retry-workspace-data">${icon('refresh',15)} Retry data</button></aside>`;
  }
  let lastRenderedWorkspaceView = null;
  function render(){
    if(!session||!profile){mobile=false;document.body.style.overflow='';renderAuth();return;}
    // A route change always closes the mobile menu and releases the document scroll lock.
    if(lastRenderedWorkspaceView!==null&&lastRenderedWorkspaceView!==view)mobile=false;
    // Keep document scrolling enabled on touch devices; the menu has its own scroll container.
    document.body.style.overflow='';
    // Label accounts use internal operations workflows, not the artist-facing support form.
    if(isAdmin()&&view==='support'){view='dashboard';if(typeof syncHash==='function')syncHash();}
    if(typeof rememberPortalView==='function')rememberPortalView();
    const routeChanged = lastRenderedWorkspaceView !== null && lastRenderedWorkspaceView !== view;
    if(routeChanged){try{window.scrollTo({top:0,left:0,behavior:'auto'});}catch(_){window.scrollTo(0,0);}}
    lastRenderedWorkspaceView = view;
    const page=view==='dashboard'?dashboard():view==='podcasts'?podcastsView():view==='builder'?builder():view==='release'?detail():view==='settings'?settings():view==='support'?supportView():view==='earnings'?earningsView():view==='statements'?statementsView():view==='operations'?operationsView():view==='notifications'?notesView():view==='bands'?bandsView():view==='roster'?roster():view==='discover'?discover():view==='discography'?discography():view==='calendar'?calendarView():view==='insights'?insightsView():view==='pipeline'?pipelineView():view==='studio'?studioView():view==='vault'?vaultView():view==='business'?businessView():view==='activity'?activityView():view==='profile'?profilePage():view==='editprofile'?editProfile():dashboard();
    $('#app').innerHTML=`<div class="shell ${sidebarCollapsed()?'sidebar-collapsed':''}">${nav()}<main id="main-content" class="main ${routeChanged?'route-enter':''}" tabindex="-1">${workspaceBannerMarkup()}${workspaceTopbar()}${workspaceDataWarningMarkup()}${page}<footer class="workspace-legal-footer" aria-label="Legal and help"><span>© ${new Date().getFullYear()} Imposed Entertainment</span><nav aria-label="Policies"><a href="/privacy">Privacy Policy</a><a href="/terms">Terms of Service</a>${isAdmin()?"":`<button type="button" class="workspace-legal-contact" data-action="support">Help &amp; support</button>`}</nav></footer></main></div>`;
    enhanceNavigation();bind();window.dispatchEvent(new CustomEvent('ie-view-rendered'));setTimeout(hydrateCovers,0);
    // Decode images off the critical path and defer below-the-fold media. The global error handler
    // in index.html replaces failed images with accessible fallbacks.
    document.querySelectorAll('#main-content img').forEach(img=>{
      if(!img.hasAttribute('decoding')) img.decoding='async';
      const r=img.getBoundingClientRect();
      const near=r.bottom>0&&r.top<window.innerHeight*.9;
      if(!img.hasAttribute('loading'))img.loading=near?'eager':'lazy';
      if(!img.hasAttribute('fetchpriority'))img.fetchPriority=near?'high':'low';
      if(img.complete&&img.naturalWidth>0)img.classList.add('media-loaded');
      else if(!img.dataset.mediaLoadBound){img.dataset.mediaLoadBound='1';img.addEventListener('load',()=>img.classList.add('media-loaded'),{once:true});}
    });
    document.querySelectorAll('.icon-btn:not([aria-label])').forEach(b=>b.setAttribute('aria-label',b.title||(/[\u2715\u00d7]/.test(b.textContent)?'Delete':String(b.dataset.action||'Action').replace(/-/g,' '))));
    syncHash();if(view==='release')setTimeout(loadTracks,0);if(view==='settings')showUsage();document.title=(unreadVisibleCount()>0?`(${unreadVisibleCount()}) `:'')+'Imposed Entertainment | Portal';
  }
  function activityView(){const open=tasks.filter(t=>!t.done&&(taskMine(t)||t.assigned_to===session.user.id)).sort((a,b)=>(a.due_date||'9999').localeCompare(b.due_date||'9999'));const visibleEvents=(recentEvents||[]).slice(0,12);return `<section class="page fade"><div class="page-heading"><p class="eyebrow">WORKSPACE</p><h1>Tasks &amp; activity</h1><p class="sub">A focused view of work that needs attention and recent release changes. Notifications live in their own inbox.</p><div class="page-heading-actions"><button class="secondary" data-action="notifications">${icon('bell',15)} Open notifications ${unreadVisibleCount()?`<span class="count-chip">${unreadVisibleCount()}</span>`:''}</button><button class="secondary" data-action="calendar">${icon('calendar',15)} Calendar</button></div></div><div class="activity-summary metrics"><div class="metric"><span>Open tasks</span><strong>${open.length}</strong><small>Across visible releases</small></div><div class="metric"><span>Overdue</span><strong>${open.filter(t=>t.due_date&&t.due_date<localDateKey()).length}</strong><small>Needs attention</small></div></div><div class="card activity-panel"><div class="section-head"><h2>Open tasks</h2><button class="secondary" data-action="calendar">Open calendar</button></div>${open.length?open.map(t=>taskRow(t,true)).join(''):'<p class="muted">All caught up. Add a campaign checklist from a release page.</p>'}</div><div class="card activity-panel"><div class="section-head"><h2>Recent release activity</h2><span class="pill neutral">Latest ${visibleEvents.length}</span></div>${visibleEvents.length?visibleEvents.map(e=>{const r=releases.find(x=>x.id===e.release_id);return `<button class="activity-event" data-action="calendar-task" data-release="${esc(e.release_id)}"><span class="activity-dot"></span><span><b>${esc(String(e.event_type||'Update').replace(/_/g,' '))}</b><small>${esc(r?.title||'Release')} · ${ago(e.created_at)}</small></span></button>`}).join(''):'<p class="muted">No recent release events available.</p>'}</div></section>`;}

  function calendarView(){
    const y=calendarCursor.getFullYear(), m=calendarCursor.getMonth(), first=new Date(y,m,1), offset=(first.getDay()+6)%7, days=new Date(y,m+1,0).getDate();
    const key=d=>`${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
    const releaseEvents=releases.filter(r=>r.release_date&&r.status!=='Rejected').map(r=>({date:r.release_date,title:r.title,sub:`${r.artist_name||'Artist'} · ${statusLabel(r.status)}`,kind:'release',id:r.id}));
    const taskEvents=tasks.filter(t=>t.due_date&&!t.done&&(isAdmin()||t.assignee==='artist')).map(t=>({date:t.due_date,title:t.title,sub:`${releases.find(r=>r.id===t.release_id)?.title||'Release'} · ${t.assignee==='label'?'Label':'Artist'} task`,kind:'task',id:t.id,release_id:t.release_id,overdue:t.due_date<localDateKey()}));
    const events=[...releaseEvents,...taskEvents], byDay={}; events.forEach(e=>(byDay[e.date]=byDay[e.date]||[]).push(e));
    const cells=[]; for(let i=0;i<offset;i++)cells.push('<div class="cal-cell cal-blank" aria-hidden="true"></div>');
    for(let d=1;d<=days;d++){const date=key(d),today=date===localDateKey(),items=byDay[date]||[];cells.push(`<div class="cal-cell ${today?'today':''}"><div class="cal-date"><b>${d}</b>${today?'<small>Today</small>':''}</div><div class="cal-events">${items.slice(0,3).map(e=>e.kind==='release'?`<button class="cal-event release" data-action="open" data-release="${esc(e.id)}" title="${esc(e.title+' — '+e.sub)}">${esc(e.title)}</button>`:`<button class="cal-event task ${e.overdue?'overdue':''}" data-action="calendar-task" data-task-id="${esc(e.id)}" data-release="${esc(e.release_id)}" title="${esc(e.title+' — '+e.sub)}">${esc(e.title)}</button>`).join('')}${items.length>3?`<small class="cal-more">+${items.length-3} more</small>`:''}</div></div>`);}
    const monthLabel=calendarCursor.toLocaleDateString(currentLocale(),{month:'long',year:'numeric'});
    const upcoming=events.filter(e=>e.date>=localDateKey()).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,8);
    return `<section class="page fade"><div class="hero-row"><div><p class="eyebrow">PLANNING</p><h1>Release calendar</h1><p class="sub">Release dates and outstanding rollout tasks in one place. All dates use your release records.</p></div><div class="row-actions"><button class="secondary" data-action="calendar-prev" aria-label="Previous month">←</button><button class="secondary" data-action="calendar-today">Today</button><button class="secondary" data-action="calendar-next" aria-label="Next month">→</button></div></div><div class="cal-toolbar"><h2>${esc(monthLabel)}</h2><div class="cal-legend"><span><i class="release"></i>Release</span><span><i class="task"></i>Task deadline</span></div></div><div class="calendar-grid"><div class="cal-weekday">Mon</div><div class="cal-weekday">Tue</div><div class="cal-weekday">Wed</div><div class="cal-weekday">Thu</div><div class="cal-weekday">Fri</div><div class="cal-weekday">Sat</div><div class="cal-weekday">Sun</div>${cells.join('')}</div><div class="section-head"><div><p class="eyebrow">NEXT UP</p><h2>Upcoming dates</h2></div></div><div class="card cal-upcoming">${upcoming.map(e=>`<div class="roster-row"><div class="cal-mini-date"><b>${esc(dateFmt(e.date))}</b><small>${e.kind==='release'?'Release':'Task deadline'}</small></div><div class="release-info"><strong>${esc(e.title)}</strong><span>${esc(e.sub)}</span></div>${e.kind==='release'?`<button class="secondary" data-action="open" data-release="${esc(e.id)}">Open</button>`:`<button class="secondary" data-action="calendar-task" data-task-id="${esc(e.id)}" data-release="${esc(e.release_id)}">Open release</button>`}</div>`).join('')||'<p class="muted">Nothing scheduled in the upcoming dates yet.</p>'}</div></section>`;
  }

  function pipelineView(){
    const stages=[
      {name:'Draft',title:'In progress',hint:'Build the release'},
      {name:'Submitted',title:'Needs review',hint:'Waiting on label'},
      {name:'Changes Requested',title:'Revisions',hint:'Artist action'},
      {name:'Approved',title:'Approved',hint:'Ready for delivery'},
      {name:'Sent to distributor',title:'In delivery',hint:'Processing'},
      {name:'Live',title:'Live',hint:'Out in the world'},
      {name:'Rejected',title:'Closed',hint:'Not proceeding'}
    ];
    const today=localDateKey();
    const visibleTasks=tasks.filter(t=>!t.done&&(isAdmin()||t.assignee==='artist'||t.assigned_to===session.user.id));
    const overdue=visibleTasks.filter(t=>t.due_date&&t.due_date<today).length;
    const dueSoon=visibleTasks.filter(t=>t.due_date&&t.due_date>=today&&t.due_date<=localDateKey(new Date(Date.now()+7*86400000))).length;
    const filteredReleases=releases.filter(r=>{const q=String(pipelineSearch||'').trim().toLocaleLowerCase();const text=`${r.title||''} ${r.artist_name||''} ${r.status||''}`.toLocaleLowerCase();if(q&&!text.includes(q))return false;if(pipelineFilter==='attention'&&!['Submitted','Changes Requested'].includes(r.status))return false;if(pipelineFilter==='upcoming'&&(!r.release_date||r.release_date<today||r.status==='Rejected'))return false;if(pipelineFilter==='overdue'&&!visibleTasks.some(t=>String(t.release_id)===String(r.id)&&t.due_date&&t.due_date<today))return false;return true;});
    const filteredIds=new Set(filteredReleases.map(r=>String(r.id)));const filteredTasks=visibleTasks.filter(t=>filteredIds.has(String(t.release_id)));const filteredOverdue=filteredTasks.filter(t=>t.due_date&&t.due_date<today).length;const filteredDueSoon=filteredTasks.filter(t=>t.due_date&&t.due_date>=today&&t.due_date<=localDateKey(new Date(Date.now()+7*86400000))).length;
    const releaseCard=r=>{const rt=visibleTasks.filter(t=>String(t.release_id)===String(r.id));const late=rt.filter(t=>t.due_date&&t.due_date<today).length;return `<article class="pipeline-card"><div class="pipeline-card-top"><span class="pill ${statusClass(r.status)}">${esc(statusLabel(r.status))}</span><span class="pipeline-task-count">${rt.length} open task${rt.length===1?'':'s'}</span></div><h3>${esc(r.title||'Untitled release')}</h3><p>${esc(r.artist_name||profile.display_name||'Artist')}</p><div class="pipeline-card-meta"><span>${icon('calendar',13)} ${esc(dateFmt(r.release_date))}</span>${late?`<span class="pipeline-overdue">${late} overdue</span>`:''}</div><button class="secondary full" data-action="pipeline-open" data-release="${esc(r.id)}">${isAdmin()&&['Submitted','Changes Requested'].includes(r.status)?'Review release':'Open release'} ${icon('arrow',13)}</button></article>`;};
    return `<section class="page fade pipeline-page"><div class="hero-row"><div><p class="eyebrow">WORKFLOW STUDIO</p><h1>Release pipeline</h1><p class="sub">One shared view of release progress, review queues and next actions. Statuses reflect saved release records.</p></div><div class="row-actions">${isAdmin()?`<button class="secondary" data-action="roster">${icon('users',15)} Manage roster</button>`:`<button class="primary" data-action="new">${icon('plus',15)} New release</button>`}</div></div><div class="pipeline-summary metrics"><div class="metric"><span>Releases in view</span><strong>${filteredReleases.length}</strong><small>Visible to this account</small></div><div class="metric"><span>Need attention</span><strong>${filteredReleases.filter(r=>['Submitted','Changes Requested'].includes(r.status)).length}</strong><small>Review or revision</small></div><div class="metric"><span>Open tasks</span><strong>${filteredTasks.length}</strong><small>Tasks in filtered releases</small></div><div class="metric ${filteredOverdue?'metric-alert':''}"><span>Overdue tasks</span><strong>${filteredOverdue}</strong><small>${filteredDueSoon} due in the next 7 days</small></div></div><div class="pipeline-tools"><label class="pipeline-search-wrap"><span class="sr-only">Search releases</span><input id="pipeline-search" type="search" value="${esc(pipelineSearch)}" placeholder="Search releases, artists or status…" autocomplete="off"></label><label class="pipeline-filter-wrap"><span class="sr-only">Filter releases</span><select id="pipeline-filter"><option value="All" ${pipelineFilter==='All'?'selected':''}>All releases</option><option value="attention" ${pipelineFilter==='attention'?'selected':''}>Needs attention</option><option value="upcoming" ${pipelineFilter==='upcoming'?'selected':''}>Upcoming</option><option value="overdue" ${pipelineFilter==='overdue'?'selected':''}>Overdue tasks</option></select></label><span class="pipeline-result-count">${filteredReleases.length} matching release${filteredReleases.length===1?'':'s'}</span></div><div class="pipeline-board" aria-label="Release workflow stages">${stages.map(stage=>{const rows=filteredReleases.filter(r=>r.status===stage.name).sort((a,b)=>(a.release_date||'9999').localeCompare(b.release_date||'9999'));return `<section class="pipeline-column pipeline-${stage.name.toLowerCase().replace(/[^a-z]+/g,'-')}"><header class="pipeline-column-head"><div><h2>${esc(stage.title)}</h2><p>${esc(stage.hint)}</p></div><span class="pipeline-count">${rows.length}</span></header><div class="pipeline-column-cards">${rows.length?rows.map(releaseCard).join(''):`<div class="pipeline-empty">No releases here</div>`}</div></section>`;}).join('')}</div><p class="muted pipeline-footnote">Permissions are enforced by Supabase policies. This board does not grant extra access or change release status directly; open a release to use its existing review controls.</p></section>`;
  }

  function insightsView(){
    const counts={Draft:0,Submitted:0,Approved:0,Live:0,'Changes Requested':0,Rejected:0};
    releases.forEach(r=>{const k=counts[r.status]!==undefined?r.status:'Draft';counts[k]++;});
    const total=releases.length, live=counts.Live, review=counts.Submitted+counts['Changes Requested'], draft=counts.Draft;
    const denominator=Math.max(1,total);
    const bars=[['Draft',counts.Draft,'#8b95a7'],['In review',review,'#d6b46a'],['Approved',counts.Approved,'#7d9df2'],['Live',live,'#64c7a1'],['Rejected',counts.Rejected,'#d87979']];
    const upcoming=releases.filter(r=>r.release_date&&r.release_date>=localDateKey()&&r.status!=='Rejected').sort((a,b)=>a.release_date.localeCompare(b.release_date)).slice(0,5);
    const completion=total?Math.round(live/total*100):0;
    return `<section class="page fade"><div class="hero-row"><div><p class="eyebrow">PERFORMANCE OVERVIEW</p><h1>Insights</h1><p class="sub">A clear view of your release pipeline, built from your saved portal records—not estimated streams.</p></div><button class="secondary" data-action="calendar">${icon('calendar',16)} Open calendar</button></div><div class="metrics insights-metrics"><div class="metric"><span>Total releases</span><strong>${total}</strong><small>Records visible to this account</small></div><div class="metric"><span>Live catalogue</span><strong>${live}</strong><small>${completion}% of all releases</small></div><div class="metric"><span>Needs attention</span><strong>${review}</strong><small>Submitted or changes requested</small></div><div class="metric"><span>Drafts</span><strong>${draft}</strong><small>Not yet submitted</small></div></div><div class="insights-layout"><section class="card insights-panel"><div class="section-head"><div><p class="eyebrow blue">CATALOGUE HEALTH</p><h2>Release pipeline</h2></div><span class="pill neutral">${total} total</span></div>${bars.map(([label,value,color])=>`<div class="insight-bar-row"><div><span>${label}</span><b>${value}</b></div><div class="insight-track"><i style="width:${Math.round(value/denominator*100)}%;--bar-color:${color}"></i></div></div>`).join('')}<p class="muted insight-footnote">Counts reflect release statuses currently available to your account. External streaming plays and audience reach are not connected yet.</p></section><section class="card insights-panel"><div class="section-head"><div><p class="eyebrow blue">WHAT'S NEXT</p><h2>Upcoming releases</h2></div></div>${upcoming.length?upcoming.map(r=>`<button class="insight-upcoming" data-action="open" data-release="${esc(r.id)}"><span class="insight-date">${esc(dateFmt(r.release_date))}</span><span><b>${esc(r.title||'Untitled release')}</b><small>${esc(r.artist_name||profile.display_name||'Artist')}</small></span><span class="pill ${statusClass(r.status)}">${esc(statusLabel(r.status))}</span></button>`).join(''):'<p class="muted">No upcoming release dates. Add a release date to your next project to see it here.</p>'}<button class="secondary full" style="margin-top:12px" data-action="discography">Open discography ${icon('arrow',14)}</button></section></div></section>`;
  }

  function dashboardActionCentre(){
    const today=new Date(); today.setHours(0,0,0,0);
    const dayISO=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
    const todayISO=dayISO(today), in14=new Date(today); in14.setDate(in14.getDate()+14); const horizonISO=dayISO(in14);
    const items=[];
    if(isAdmin()){
      const submitted=releases.filter(r=>r.status==='Submitted');
      const changesNeeded=releases.filter(r=>r.status==='Changes Requested');
      if(submitted.length)items.push({tone:'urgent',icon:'check',count:submitted.length,title:`${submitted.length} release${submitted.length===1?'':'s'} waiting for review`,detail:'Open submissions and give artists a clear next step.',action:'pipeline',cta:'Review submissions'});
      if(changesNeeded.length)items.push({tone:'attention',icon:'mail',count:changesNeeded.length,title:`${changesNeeded.length} release${changesNeeded.length===1?'':'s'} need a follow-up`,detail:'Changes have been requested; check the latest status and notes.',action:'pipeline',cta:'Open pipeline'});
      const undated=releases.filter(r=>['Approved','Sent to distributor'].includes(r.status)&&!r.release_date);
      if(undated.length)items.push({tone:'attention',icon:'calendar',count:undated.length,title:`${undated.length} approved release${undated.length===1?'':'s'} missing a date`,detail:'Add release dates so the team can plan delivery.',action:'discography',cta:'Check catalogue'});
    }else{
      const changesNeeded=releases.filter(r=>r.status==='Changes Requested');
      changesNeeded.slice(0,3).forEach(r=>items.push({tone:'urgent',icon:'mail',title:`Update “${r.title||'Untitled release'}”`,detail:r.review_note||'The label has requested changes before this can move forward.',action:'open',release:r.id,cta:'Review feedback'}));
      const drafts=releases.filter(r=>r.status==='Draft').sort((a,b)=>String(b.updated_at||'').localeCompare(String(a.updated_at||'')));
      if(drafts.length)items.push({tone:'next',icon:'edit',count:drafts.length,title:`Pick up ${drafts.length===1?'your draft':`${drafts.length} drafts`}`,detail:'Continue adding track details, artwork and delivery information.',action:'open',release:drafts[0].id,cta:'Continue draft'});
      const dueSoon=releases.filter(r=>r.release_date&&r.release_date>=todayISO&&r.release_date<=horizonISO&&r.status!=='Rejected'&&r.status!=='Live').sort((a,b)=>a.release_date.localeCompare(b.release_date));
      if(dueSoon.length)items.push({tone:'attention',icon:'calendar',count:dueSoon.length,title:`${dueSoon.length} upcoming release${dueSoon.length===1?'':'s'} in the next 14 days`,detail:'Double-check the release details and any outstanding feedback.',action:'calendar',cta:'Check dates'});
    }
    const visible=items.slice(0,4);
    return `<section class="action-centre" aria-labelledby="action-centre-title"><div class="action-centre-head"><div><span class="panel-kicker">YOUR NEXT MOVES</span><h2 id="action-centre-title">Action centre</h2><p>${visible.length?`Prioritised from your current release data. ${items.length>visible.length?`${items.length-visible.length} more item${items.length-visible.length===1?'':'s'} can be found in your workspace.`:''}`:'Nothing urgent is waiting on you right now.'}</p></div><span class="action-centre-count ${visible.length?'has-actions':''}">${visible.length?`${visible.length} ${visible.length===1?'item':'items'}`:'All clear'}</span></div>${visible.length?`<div class="action-centre-list">${visible.map((it,i)=>`<article class="action-centre-item ${it.tone}"><span class="action-centre-icon">${icon(it.icon,18)}</span><div class="action-centre-copy"><b>${esc(it.title)}</b><p>${esc(it.detail)}</p></div>${it.count?`<span class="action-centre-number">${it.count}</span>`:''}<button class="action-centre-cta" data-action="${it.action}" ${it.release?`data-release="${esc(it.release)}"`:''}>${esc(it.cta)} ${icon('arrow',14)}</button></article>`).join('')}</div>`:`<div class="action-centre-clear"><span class="action-clear-check">${icon('check',18)}</span><div><b>You’re in good shape.</b><p>When a release needs attention, it’ll appear here with a direct route to the next step.</p></div><button class="secondary" data-action="${isAdmin()?'pipeline':'new'}">${isAdmin()?'View pipeline':'Start a release'} ${icon('arrow',14)}</button></div>`}</section>`;
  }

  function dashboard(){
    const displayPrefs=getAppearancePreferences().dashboard;
    const layoutPrefs=getAppearancePreferences().dashboardLayout;
    const widget=(key,label,content)=>content?'<section class="dashboard-widget" data-dashboard-widget-card="'+key+'" data-widget-size="'+(layoutPrefs.sizes[key]||'full')+'" data-widget-shape="'+(layoutPrefs.shapes[key]||'soft')+'"><div class="dashboard-widget-tools" aria-label="Customise '+label+'"><span class="dashboard-drag-handle" draggable="false" data-dashboard-drag="'+key+'" title="Drag to move" aria-label="Drag to reorder '+label+'">⠿</span><button type="button" data-dashboard-move="up" data-widget="'+key+'" aria-label="Move '+label+' up">↑</button><button type="button" data-dashboard-move="down" data-widget="'+key+'" aria-label="Move '+label+' down">↓</button><label>Width<select data-dashboard-size="'+key+'" aria-label="'+label+' width"><option value="full">Full</option><option value="half">Half</option><option value="third">One third</option></select></label><label>Shape<select data-dashboard-shape="'+key+'" aria-label="'+label+' shape"><option value="soft">Rounded</option><option value="square">Square</option><option value="pill">Extra round</option></select></label></div>'+content+'</section>':'';

    const FS={'Needs review':['Submitted','Changes Requested'],Approved:['Approved'],Live:['Live']};
    const list=releases.filter(r=>(!search||`${r.title} ${r.artist_name}`.toLowerCase().includes(search.toLowerCase()))&&(filter==='All'||FS[filter].includes(r.status)));
    const pending=releases.filter(r=>['Submitted','Changes Requested'].includes(r.status));
    const live=releases.filter(r=>r.status==='Live');
    const changes=releases.filter(r=>r.status==='Changes Requested');
    const arts=users.filter(u=>!isAdminRole(u.role)).length;
    const localToday=new Date(); localToday.setHours(0,0,0,0);
    const today=`${localToday.getFullYear()}-${String(localToday.getMonth()+1).padStart(2,'0')}-${String(localToday.getDate()).padStart(2,'0')}`;
    const upcoming=releases.filter(r=>r.release_date&&r.release_date>=today&&r.status!=='Rejected').sort((a,b)=>a.release_date.localeCompare(b.release_date)).slice(0,4);
    const drafts=releases.filter(r=>r.status==='Draft');
    const releaseAction=isAdmin()?`<button class="primary large" data-action="roster">${icon('users',17)} Invite an artist</button>`:`<button class="primary large" data-action="new">${icon('plus',18)} Create release</button>`;
    const metrics=isAdmin()?`<div class="metrics"><div class="metric metric-artists"><span>ARTISTS</span><strong>${arts}</strong><small>${icon('users',13)} On your roster</small></div><div class="metric metric-bands"><span>BANDS</span><strong>${bands.length}</strong><small>${icon('users',13)} Active groups</small></div><div class="metric metric-review"><span>NEEDS REVIEW</span><strong>${pending.length}</strong><small>${pending.length?'Waiting on you':'All caught up'}</small></div><div class="metric metric-live"><span>LIVE RELEASES</span><strong>${live.length}</strong><small>${icon('disc',13)} Published catalogue</small></div></div>`:`<div class="metrics"><div class="metric metric-releases"><span>YOUR CATALOGUE</span><strong>${releases.length}</strong><small>${icon('disc',13)} Total releases</small></div><div class="metric metric-review"><span>IN REVIEW</span><strong>${pending.length}</strong><small>${pending.length?'Needs attention':'Nothing waiting'}</small></div><div class="metric metric-live"><span>LIVE RELEASES</span><strong>${live.length}</strong><small>${icon('disc',13)} Out in the world</small></div><div class="metric metric-drafts"><span>DRAFTS</span><strong>${drafts.length}</strong><small>${icon('edit',13)} Work in progress</small></div></div>`;
    const upcomingHtml=upcoming.length?`<section class="dashboard-panel upcoming-panel"><div class="panel-heading"><div><span class="panel-kicker">UPCOMING RELEASES</span><h2>Coming up</h2></div><button class="quiet-link" data-action="calendar">Full calendar ${icon('arrow',14)}</button></div><div class="up-strip">${upcoming.map(r=>{const d=new Date(r.release_date+'T00:00');return `<button class="up-card" data-action="open" data-release="${r.id}"><span class="up-date"><b>${d.getDate()}</b>${d.toLocaleDateString(currentLocale(),{month:'short'})}</span><span class="up-info"><b>${esc(r.title)}</b><small>${esc(r.artist_name)}</small></span><span class="pill ${statusClass(r.status)}">${esc(statusLabel(r.status))}</span></button>`;}).join('')}</div></section>`:`${isAdmin()?`<section class="dashboard-panel next-step-panel"><span class="panel-kicker">YOUR NEXT MOVE</span><h2>Keep your release calendar moving.</h2><p>Invite artists or review the pipeline to get upcoming releases onto the schedule.</p><button class="secondary" data-action="roster">Manage artist roster ${icon('arrow',14)}</button><button class="secondary" data-action="pipeline">Open release pipeline ${icon('arrow',14)}</button></section>`:`<section class="dashboard-panel next-step-panel"><span class="panel-kicker">YOUR NEXT MOVE</span><h2>Start your first release.</h2><p>Create a draft to add tracks, artwork, release details and delivery information.</p><button class="secondary" data-action="new">Start a release ${icon('arrow',14)}</button></section>`}`;
    return `<section class="page fade dashboard-page">
      <section class="dashboard-hero"><div class="dashboard-hero-copy"><span class="hero-overline"><i></i>${isAdmin()?'LABEL WORKSPACE':'ARTIST WORKSPACE'} <span> / </span> OVERVIEW</span><h1>${greet()}${firstName()?', '+esc(firstName()):''}.</h1><p>${isAdmin()?'Review submissions, monitor release dates and manage your artist roster.':'Track your releases, review feedback and keep upcoming deadlines in view.'}</p><div class="dashboard-hero-actions">${releaseAction}<button class="hero-secondary" data-action="discography">Open catalogue ${icon('arrow',15)}</button><button type="button" class="hero-secondary dashboard-customise-toggle" data-dashboard-edit-toggle aria-pressed="false">Customise layout</button><button type="button" class="hero-secondary dashboard-reset-layout" data-dashboard-reset>Reset layout</button></div></div><div class="hero-art ${upcoming.length?'hero-art-featured':''}" ${upcoming.length?'':'aria-hidden="true"'}>${upcoming.length?`<button class="hero-featured-release" type="button" data-action="open" data-release="${esc(upcoming[0].id)}" aria-label="Open upcoming release ${esc(upcoming[0].title)}"><span class="hero-featured-cover" data-cover="${esc(upcoming[0].id)}">${coverHtml(upcoming[0])}</span><span class="hero-featured-meta"><small>NEXT RELEASE</small><b>${esc(upcoming[0].title)}</b><em>${dateFmt(upcoming[0].release_date)}</em></span></button>`:`<div class="hero-art-glow"></div><div class="hero-record"><div class="hero-record-label"><span>IE</span><i></i></div></div><div class="hero-art-caption">INDEPENDENT<br>BY DESIGN</div>`}</div><div class="hero-index">IE<span> / </span>001</div></section>
      <div class="dashboard-widget-layout">${widget('metrics','Summary metrics',displayPrefs.metrics?metrics:'')}
      ${widget('actions','Action centre',dashboardActionCentre())}
      ${widget('upcoming','Upcoming releases',displayPrefs.upcoming?upcomingHtml:'')}
      <section class="dashboard-widget" data-dashboard-widget-card="shortcuts" data-widget-size="${layoutPrefs.sizes.shortcuts}" data-widget-shape="${layoutPrefs.shapes.shortcuts}"><div class="dashboard-widget-tools"><span class="dashboard-drag-handle" draggable="false" data-dashboard-drag="shortcuts">⠿</span><button type="button" data-dashboard-move="up" data-widget="shortcuts">↑</button><button type="button" data-dashboard-move="down" data-widget="shortcuts">↓</button><label>Width<select data-dashboard-size="shortcuts"><option value="full">Full</option><option value="half">Half</option><option value="third">One third</option></select></label><label>Shape<select data-dashboard-shape="shortcuts"><option value="soft">Rounded</option><option value="square">Square</option><option value="pill">Extra round</option></select></label></div><section class="dashboard-panel quick-links-panel"><div class="panel-heading"><div><span class="panel-kicker">SHORTCUTS</span><h2>${isAdmin()?'Manage your label':'Jump back in'}</h2></div></div><div class="dashboard-shortcut-grid">${isAdmin()?`<button class="quick-link-row" data-action="roster"><span class="quick-link-icon">${icon('users',17)}</span><span><b>Artist roster</b><small>Manage artists and invites</small></span>${icon('arrow',15)}</button><button class="quick-link-row" data-action="pipeline"><span class="quick-link-icon">${icon('workflow',17)}</span><span><b>Release pipeline</b><small>Review submitted releases</small></span>${icon('arrow',15)}</button><button class="quick-link-row" data-action="operations"><span class="quick-link-icon">${icon('settings',17)}</span><span><b>Operations centre</b><small>Manage label operations</small></span>${icon('arrow',15)}</button>`:`<button class="quick-link-row" data-action="studio"><span class="quick-link-icon">${icon('sparkles',17)}</span><span><b>Artist studio</b><small>Build your artist presence</small></span>${icon('arrow',15)}</button><button class="quick-link-row" data-action="vault"><span class="quick-link-icon">${icon('file',17)}</span><span><b>File vault</b><small>Find your release assets</small></span>${icon('arrow',15)}</button><button class="quick-link-row" data-action="activity"><span class="quick-link-icon">${icon('check',17)}</span><span><b>Tasks & activity</b><small>See what needs attention</small></span>${icon('arrow',15)}</button>`}</div></section></section><section class="dashboard-widget" data-dashboard-widget-card="details" data-widget-size="${layoutPrefs.sizes.details}" data-widget-shape="${layoutPrefs.shapes.details}"><div class="dashboard-widget-tools"><span class="dashboard-drag-handle" draggable="false" data-dashboard-drag="details">⠿</span><button type="button" data-dashboard-move="up" data-widget="details">↑</button><button type="button" data-dashboard-move="down" data-widget="details">↓</button><label>Width<select data-dashboard-size="details"><option value="full">Full</option><option value="half">Half</option><option value="third">One third</option></select></label><label>Shape<select data-dashboard-shape="details"><option value="soft">Rounded</option><option value="square">Square</option><option value="pill">Extra round</option></select></label></div><details class="dashboard-more"><summary><span><b>More dashboard details</b><small>Tasks, updates, insights and full release list</small></span><span class="dashboard-more-toggle" aria-hidden="true">+</span></summary><div class="dashboard-more-content">
      ${displayPrefs.tasks?todoCard():''}
      ${isAdmin()?adminInsights():''}
      ${displayPrefs.announcements?announceHtml():''}
      ${displayPrefs.activity?`<section class="dashboard-panel dashboard-recent-panel"><div class="panel-heading"><div><span class="panel-kicker">LATEST UPDATES</span><h2>Recent activity</h2></div><button class="quiet-link" data-action="activity">All activity ${icon('arrow',14)}</button></div>${recentEvents.length?`<div class="dashboard-recent-list">${recentEvents.slice(0,4).map(e=>{const r=releases.find(x=>x.id===e.release_id);return `<button class="dashboard-recent-item" data-action="calendar-task" data-release="${esc(e.release_id||'')}"><span class="dashboard-recent-dot"></span><span><b>${esc(String(e.event_type||'Update').replace(/_/g,' '))}</b><small>${esc(r?.title||'Release update')}</small></span><time datetime="${esc(e.created_at||'')}">${ago(e.created_at)}</time></button>`;}).join('')}</div>`:'<p class="muted dashboard-recent-empty">Your latest release updates will appear here.</p>'}</section>
      `:''}
      ${!isAdmin()&&changes.length?`<section class="dashboard-panel changes-panel"><div class="panel-heading"><div><span class="panel-kicker">ACTION NEEDED</span><h2>Changes requested</h2></div></div><div class="approval-grid">${changes.map(approval).join('')}</div></section>`:''}
      ${displayPrefs.catalogue?`<section class="dashboard-panel catalogue-panel"><div class="panel-heading catalogue-heading"><div><span class="panel-kicker">YOUR MUSIC, IN MOTION</span><h2>${isAdmin()?'All releases':'Your releases'}</h2><p>${isAdmin()?'Track every submission across your label.':'Keep tabs on drafts, reviews and releases already out in the world.'}</p></div><div class="catalogue-tools"><div class="search">${icon('search',16)}<input id="search" value="${esc(search)}" placeholder="Search releases…"></div><button class="secondary" data-action="export-releases">Export CSV</button><button class="secondary" data-action="discography">View discography ${icon('arrow',14)}</button></div></div><div class="chips">${['All','Needs review','Approved','Live'].map(f=>`<button class="chip ${filter===f?'active':''}" data-action="filter" data-f="${f}">${!isAdmin()&&f==='Needs review'?'In review':f}</button>`).join('')}</div>${list.length?`<div class="release-list">${list.map(row).join('')}</div>`:`<div class="empty"><div class="empty-icon">${icon('disc',25)}</div><h3>${isAdmin()?'Nothing to review yet':'Your catalogue starts here'}</h3><p>${isAdmin()?'Artists create and submit releases here for your approval. Invite your first artist to get started.':'Create your first release, add tracks and artwork, then submit it to the label.'}</p>${isAdmin()?`<button class="primary" data-action="roster">${icon('plus',16)} Invite an artist</button>`:`<button class="primary" data-action="new">${icon('plus',16)} Create release</button>`}</div>`}</section>`:''}
      </div></details></section>
      </div>
    </section>`;
  }

  function approval(r){return `<article class="approval-card"><div class="approval-top"><span class="pill ${statusClass(r.status)}">${esc(statusLabel(r.status))}</span><span class="date">${dateFmt(r.updated_at?.slice(0,10))}</span></div><h3>${esc(r.title)}</h3><p>${esc(r.artist_name)}</p>${r.review_note&&r.status==='Changes Requested'?`<p class="review-note">${esc(r.review_note)}</p>`:''}<div class="approval-actions"><button class="secondary" data-action="open" data-release="${r.id}">${icon('eye',15)} Review</button>${r.status==='Submitted'?`<button class="success" data-action="approve" data-release="${r.id}">${icon('check',15)} Approve</button>`:''}</div></article>`; }
  function row(r){return `<button class="release-row" data-action="open" data-release="${r.id}"><div class="cover-mini" data-cover="${r.id}">${coverHtml(r)}</div><div class="release-info"><strong>${esc(r.title)}</strong><span>${esc(r.artist_name)} · ${esc(r.release_type)} · ${dateFmt(r.release_date)}</span></div><span class="pill ${statusClass(r.status)}">${esc(statusLabel(r.status))}</span><span class="row-arrow">${icon('arrow',17)}</span></button>`; }

  function builder(){ const r=draft, steps=['Basics','Tracks','Artwork','Distribution','Review']; return `<section class="builder fade"><div class="builder-head"><button class="back-link" data-action="cancel-builder">${icon('back',16)} ${backView==='discography'?'Discography':'Dashboard'}</button><div class="builder-title"><p class="eyebrow blue">NEW RELEASE</p><h1>${esc(r.title||'Untitled release')}</h1></div><div class="stepper">${steps.map((s,i)=>`<div class="step ${wizardStep===i+1?'current':''} ${wizardStep>i+1?'done':''}"><span>${wizardStep>i+1?icon('check',12):i+1}</span><b>${s}</b></div>`).join('')}</div></div><div class="local-draft-tools"><p class="local-draft-status" role="status">${draftDirty?'Changes are backed up on this device as you edit.':'Local recovery backup activates as you edit.'} Files not uploaded to the portal must be reselected after recovery.</p><button type="button" class="secondary small" data-action="export-local-draft">${icon('download',14)} Export backup</button></div>${readinessCard()}<div class="builder-card">${builderStep()}</div></section>`; }
  function field(label,html,hint=''){return `<label class="field"><span>${label}</span>${html}${hint?`<small>${hint}</small>`:''}</label>`;}

  function readinessCard(){const r=releaseReadiness();const pct=Math.round(r.complete/r.total*100);return `<section class="release-readiness card" aria-label="Release readiness"><div class="readiness-top"><div><p class="eyebrow">RELEASE READINESS</p><h2>${r.ready?'Ready for submission':'Complete your release checklist'}</h2><p>${r.complete} of ${r.total} checks complete${r.warnings.length?` · ${r.warnings.length} metadata ${r.warnings.length===1?'warning':'warnings'}`:''}</p></div><strong class="readiness-percent">${pct}%</strong></div><div class="readiness-meter" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${pct}"><span style="width:${pct}%"></span></div><ul class="readiness-list">${r.checks.map(([label,ok])=>`<li class="${ok?'is-complete':'is-missing'}"><span aria-hidden="true">${ok?'✓':'○'}</span>${esc(label)}</li>`).join('')}</ul>${r.warnings.length?`<div class="readiness-warnings"><b>Metadata checks</b><ul>${r.warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul></div>`:''}<p class="readiness-note">Drafts can be saved before every item is complete. Submission requires all required checks to pass.</p></section>`;}
  function builderStep(){const r=draft;if(wizardStep===1)return `<div class="step-panel"><div class="panel-title"><div><h2>Release basics</h2><p>The basics. Save a draft at any time and pick it up again from your Discography.</p></div><span class="required">REQUIRED</span></div><div class="grid-2">${field('Release title',`<input data-field="title" value="${esc(r.title)}" placeholder="e.g. Midnight Drive" required>`)}${field('Artist / project',`<input data-field="artist" value="${esc(r.artist)}" placeholder="Artist name" required>`)}${bands.length?field('Release under',`<select data-field="bandId"><option value="">Solo - my own account</option>${bands.map(b=>`<option value="${esc(b.id)}" ${r.bandId===b.id?'selected':''}>${esc(b.name)}</option>`).join('')}</select>`,'Band members can see this release.'):''}${field('Release type',`<select data-field="releaseType">${TYPES.map(x=>`<option ${r.releaseType===x?'selected':''}>${x}</option>`).join('')}</select>`)}${field('Primary genre',`<select data-field="genre">${GENRES.map(x=>`<option ${r.genre===x?'selected':''}>${x}</option>`).join('')}</select>`)}${field('Release date',`<input type="date" data-field="releaseDate" value="${esc(r.releaseDate)}">`,'Use the date it comes out, or came out.')}${field('C-line',`<input data-field="cLine" value="${esc(r.cLine)}" placeholder="© 2026 Artist">`)}${field('P-line',`<input data-field="pLine" value="${esc(r.pLine)}" placeholder="℗ 2026 Artist">`)}${field('Language of lyrics',`<select data-field="language">${['English','Spanish','French','German','Portuguese','Polish','Instrumental','Other'].map(x=>`<option ${r.language===x?'selected':''}>${x}</option>`).join('')}</select>`)}<label class="pf-check" style="align-self:end"><input type="checkbox" data-field="prevReleased" ${r.prevReleased?'checked':''}> Previously released elsewhere</label>${r.prevReleased?field('Original release date',`<input type="date" data-field="origDate" value="${esc(r.origDate)}">`):''}</div>${buttons('Continue',()=>next(2))}</div>`;
    if(wizardStep===2)return `<div class="step-panel"><div class="panel-title"><div><h2>Tracks</h2><p>Add every track that belongs on this release. Stereo FLAC (16-bit, 44.1 kHz) or MP3 (320 kbps, 44.1 kHz). WAV is not accepted.</p></div><button class="secondary" data-action="add-track">${icon('plus',15)} Add track</button></div><div class="track-list">${r.tracks.map((t,i)=>`<div class="track-card"><div class="track-num">${i+1}</div><div class="track-fields">${field('Track title',`<input data-track="${i}" data-tfield="title" value="${esc(t.title)}" placeholder="Track title">`)}${field('Version',`<input data-track="${i}" data-tfield="version" value="${esc(t.version)}" placeholder="Original / Radio Edit">`)}${field('ISRC',`<input data-track="${i}" data-tfield="isrc" value="${esc(t.isrc)}" placeholder="Optional">`)}${field('Featured artists',`<input data-track="${i}" data-tfield="featured" value="${esc(t.featured)}" placeholder="Optional">`)}${field('Songwriters / composers',`<input data-track="${i}" data-tfield="writers" value="${esc(t.writers)}" placeholder="Full legal names, comma separated" required>`)}${field('Lyrics (optional)',`<textarea data-track="${i}" data-tfield="lyrics" rows="5" maxlength="20000" placeholder="Paste the lyrics for this track…">${esc(t.lyrics||'')}</textarea>`,'Submitted privately to the label with this release. Lyrics are not shown on your public artist page.')}<label class="pf-check"><input type="checkbox" data-track="${i}" data-tfield="explicit" ${t.explicit?'checked':''}> Explicit lyrics or content</label><label class="file-line"><span>${icon('upload',15)} ${t.fileName?esc(t.fileName):(t.path?'Audio saved. Choose to replace':'Choose FLAC or MP3')}</span><input type="file" accept=".flac,.mp3,audio/flac,audio/mpeg" data-audio="${i}"></label></div>${r.tracks.length>1?`<button class="icon-btn danger-ghost" data-action="remove-track" data-index="${i}">${icon('trash',16)}</button>`:''}</div>`).join('')}</div>${buttons('Continue',()=>next(3),true)}</div>`;
    if(wizardStep===3)return `<div class="step-panel"><div class="panel-title"><div><h2>Artwork</h2><p>Exactly 3000 × 3000 px, JPG, RGB, under 25 MB. No URLs, prices or "download free" text.</p></div></div><div class="artwork-layout"><div class="art-preview">${r.artworkPreview?`<img loading="lazy" decoding="async" src="${r.artworkPreview}" alt="Artwork preview">`:`<div>${icon('image',28)}<span>NO ARTWORK</span></div>`}</div><div><label class="upload-box">${icon('upload',25)}<b>${r.artworkFile?esc(r.artworkFile.name):(r.artworkPath?'Artwork saved. Choose to replace':'Choose artwork')}</b><small>JPG only · exactly 3000 × 3000 px · RGB · under 25 MB</small><input id="art-file" type="file" accept="image/jpeg,.jpg,.jpeg" hidden></label><div class="rules"><span>JPG, RGB</span><span>3000 × 3000 exactly</span><span>Under 25 MB</span></div></div></div>${buttons('Continue',()=>next(4),true)}</div>`;
    if(wizardStep===4)return `<div class="step-panel"><div class="panel-title"><div><h2>Distribution</h2><p>Choose your preferred stores and territories for label review. Final distribution choices are confirmed during release processing.</p></div></div>${field('Territory',`<select data-field="territory">${['Worldwide','North America','Europe','Asia','South America','Africa','Oceania','Middle East'].map(x=>`<option ${r.territory===x?'selected':''}>${x}</option>`).join('')}</select>`)}<div class="store-head"><div><h3>Stores</h3><p>${r.stores.length} of ${STORES.length} selected</p></div><div><button class="text-btn" data-action="stores-all">Select all</button><button class="text-btn muted" data-action="stores-none">Clear</button></div></div><div class="stores-grid">${STORES.map(s=>`<button class="store ${r.stores.includes(s)?'selected':''}" data-action="store" data-store="${esc(s)}"><span class="check">${r.stores.includes(s)?icon('check',11):''}</span>${esc(s)}</button>`).join('')}</div><div class="streaming-link-editor"><h3>Listening links (optional)</h3><p class="muted">After a release is live, add its direct Spotify, Apple Music, YouTube Music or other listening URLs. One per line, formatted as <b>Platform | URL</b>. These appear on your public artist page.</p><label class="field"><span>Where fans can listen</span><textarea data-field="streamingLinksText" rows="4" maxlength="2400" placeholder="Spotify | https://open.spotify.com/album/…&#10;Apple Music | https://music.apple.com/…">${esc(r.streamingLinksText||'')}</textarea></label></div>${buttons('Continue',()=>next(5),true)}</div>`;
    return `<div class="step-panel"><div class="panel-title"><div><h2>Final review</h2><p>Last check before it goes to the label.</p></div></div><div class="review-grid"><div><span>Title</span><b>${esc(r.title)}</b></div><div><span>Artist</span><b>${esc(r.artist)}</b></div><div><span>Type</span><b>${esc(r.releaseType)}</b></div><div><span>Genre</span><b>${esc(r.genre)}</b></div><div><span>Release date</span><b>${esc(r.releaseDate||'Not set')}</b></div><div><span>Territory</span><b>${esc(r.territory)}</b></div><div><span>Stores</span><b>${r.stores.length} selected</b></div><div><span>Tracks</span><b>${r.tracks.length}</b></div></div>${r.artworkPreview?`<div class="review-art"><img loading="lazy" decoding="async" src="${r.artworkPreview}" alt=""><div><b>${esc(r.artworkFile?.name||'Artwork')}</b><span>Artwork attached</span></div></div>`:''}<label class="pf-check" style="margin-top:14px;align-items:flex-start"><input type="checkbox" data-field="rights" ${r.rights?'checked':''}> <span>I confirm I own or control all rights to this music and artwork, every sample and cover is cleared, all contributors are credited, and the information above is accurate.</span></label><div class="success-box" style="margin-top:14px">${icon('shield',16)} Your release files and metadata will be saved for the Imposed Entertainment team to review. You can follow the release status in your dashboard.</div>${buttons('Submit release',submitRelease,true)}</div>`; }
  function buttons(label,fn,back=false){return `<div class="builder-buttons">${back?`<button class="secondary" data-action="prev">${icon('back',15)} Back</button>`:`<button class="secondary" data-action="cancel-builder">Cancel</button>`}<button class="secondary" data-action="save-draft">Save draft</button><button class="primary" data-action="builder-next">${label} ${icon('arrow',15)}</button></div>`;}

  function releaseNextStep(r){
    const status=String(r.status||'Draft');
    let title='Keep your release moving', body='Check the release details and make sure the label has what it needs.', tone='neutral';
    if(status==='Draft'){title='Finish your release draft';body='Complete the audio, artwork, credits and distribution details, then submit it for label review.';tone='blue';}
    else if(status==='Changes Requested'){title='Changes are needed';body=r.review_note?String(r.review_note):'Review the label feedback, update the release and submit it again.';tone='amber';}
    else if(status==='Submitted'){title=isAdmin()?'Ready for label review':'Submitted for review';body=isAdmin()?'Check the artwork, audio, rights declaration and metadata before approving or requesting changes.':'Your release is with the label team. You can check its files, details and feedback here while it is reviewed.';tone='blue';}
    else if(status==='Approved'){title=isAdmin()?'Ready for distribution handoff':'Approved by the label';body=isAdmin()?'Complete the internal handoff, then mark it sent to the distributor once the upload is complete.':'The label has approved your release. The next step is distribution processing.';tone='green';}
    else if(status==='Sent to distributor'){title='Distribution processing';body='The release has been handed off for distribution. Store availability can take time to update.';tone='blue';}
    else if(status==='Live'){title='Your release is live';body='Keep your listening links current and add performance statements when they become available.';tone='green';}
    else if(status==='Rejected'){title='Release not approved';body=r.review_note?String(r.review_note):'Check the label’s feedback or contact the team to understand the decision.';tone='amber';}
    return `<aside class="release-next-step tone-${tone}" aria-label="Release next step"><span class="release-next-mark" aria-hidden="true">${status==='Live'?'✓':status==='Changes Requested'||status==='Rejected'?'!':'→'}</span><div><strong>${esc(title)}</strong><p>${esc(body)}</p></div></aside>`;
  }
  function detail(){const r=selected;if(!r&&unavailableReleaseRouteId)return `<section class="page fade"><button class="back-link" data-action="dashboard">${icon('back',16)} Dashboard</button><div class="card" style="padding:24px"><p class="eyebrow">RELEASE DETAILS</p><h1>Release details unavailable</h1><p class="muted">This release could not be loaded right now. Your page address has been preserved; retry the workspace data or return to the dashboard.</p><button class="primary" data-action="retry-workspace-data">Retry loading</button></div></section>`;if(!r)return dashboard();return `<section class="page fade"><button class="back-link" data-action="${backTarget()}">${icon('back',16)} ${backView==='discography'?'Discography':'Dashboard'}</button><div class="detail-heading"><div class="detail-cover">${icon('disc',30)}</div><div><p class="eyebrow">${esc(r.release_type)} · ${esc(statusLabel(r.status))}</p><h1>${esc(r.title)}</h1><p>${esc(r.artist_name)} · ${dateFmt(r.release_date)}</p><span class="pill ${statusClass(r.status)}">${esc(statusLabel(r.status))}</span></div></div>${releaseNextStep(r)}<div class="detail-card card"><h3>Release metadata</h3><div class="detail-metadata-grid">${[['Title',r.title],['Primary artist',r.artist_name],['Release type',r.release_type],['Release date',r.release_date||'—'],['Genre',r.genre],['Territory',r.territory],['Stores',Array.isArray(r.stores)?r.stores.length:'0'],['C-line',r.c_line||'—'],['P-line',r.p_line||'—'],['Language',r.language||'—'],['UPC',r.upc||'—'],['Previously released',r.previously_released?(r.original_release_date||'Yes'):'No'],['Rights declaration',r.rights_confirmed?'Confirmed by artist':'Not confirmed'],['Updated',dateFmt(r.updated_at?.slice(0,10))]].map(x=>`<div class="detail-line"><span>${x[0]}</span><b>${esc(x[1])}</b>${isAdmin()&&!['Updated','Stores'].includes(x[0])?`<button class="copy-btn" data-action="copy" data-text="${esc(x[1])}">Copy</button>`:''}</div>`).join('')}</div><div class="detail-actions">${isAdmin()?`<button class="secondary" data-action="copy-all">Copy all metadata</button><button class="secondary" data-action="dl-rn-sheet">Download internal handoff sheet</button>${r.artwork_path?`<button class="secondary" data-action="dl-art">Download artwork</button>`:''}`:''}${isAdmin()&&r.status==='Submitted'?`<button class="success" data-action="approve" data-release="${r.id}">${icon('check',15)} Approve</button><button class="danger-btn" data-action="changes" data-release="${r.id}">Request changes</button><button class="danger-ghost" data-action="reject" data-release="${r.id}">Reject</button>`:''}${isAdmin()&&r.status==='Approved'?`<button class="success" data-action="sent" data-release="${r.id}">${icon('check',15)} Sent to distributor</button>`:''}${isAdmin()&&r.status==='Sent to distributor'?`<button class="success" data-action="live" data-release="${r.id}">${icon('check',15)} Mark live</button>`:''}${isAdmin()&&['Approved','Sent to distributor','Live'].includes(r.status)?`<button class="secondary" data-action="changes" data-release="${r.id}">Reopen for edits</button>`:''}${!isAdmin()&&r.owner_id===session.user.id&&['Draft','Changes Requested'].includes(r.status)?`<button class="primary" data-action="disc-edit" data-release="${r.id}">${r.status==='Draft'?'Continue editing':'Edit &amp; resubmit'}</button>`:''}${!isAdmin()&&r.owner_id===session.user.id?`<button class="secondary" data-action="disc-dup" data-release="${r.id}">Duplicate as new draft</button>`:''}${isAdmin()?`<button class="secondary" data-action="set-upc" data-release="${r.id}">Set UPC</button>`:''}${!isAdmin()&&['Submitted','Approved','Sent to distributor','Live'].includes(r.status)?`<button class="secondary" data-action="disc-request" data-release="${r.id}">Request update</button>`:''}</div></div>${rolloutCard(r)}${statsCard(r)}<div class="detail-card card"><h3>Release links</h3><p class="muted">Campaign, streaming and reference links attached to this release.</p><div id="detail-release-links"><p class="muted">Loading links…</p></div>${isAdmin()?`<div class="invite-form release-link-form"><label class="field"><span>Platform / label</span><input id="rl-platform" maxlength=80 placeholder="e.g. Spotify"></label><label class="field"><span>URL</span><input id="rl-url" type="url" maxlength=1000 placeholder="https://…"></label><button class="primary" data-action="release-link-add" data-release="${r.id}">Add link</button></div>`:''}</div>${isAdmin()?`<div class="detail-card card handoff"><h3>Release processing</h3><p class="muted">Work through these in order, then move the release along. The artist sees a neutral status and never the distributor's name.</p><div class="handoff-grid"><div class="handoff-tile"><b>1 · Artwork</b>${r.artwork_path?`<button class="secondary" data-action="dl-art">Download cover</button>`:'<span class="pill red">Missing</span>'}</div><div class="handoff-tile"><b>2 · Audio</b><button class="secondary" data-action="dl-all-audio">Download all tracks</button></div><div class="handoff-tile"><b>3 · Metadata</b><button class="secondary" data-action="copy-all">Copy all metadata</button><button class="secondary" data-action="dl-rn-sheet">Download internal handoff sheet</button>${r.metadata_path?`<button class="secondary" data-action="dl-meta">Download JSON</button>`:''}</div><div class="handoff-tile"><b>4 · Done</b>${r.status==='Approved'?`<button class="success" data-action="sent" data-release="${r.id}">Sent to distributor</button>`:r.status==='Sent to distributor'?`<button class="success" data-action="live" data-release="${r.id}">Mark live</button>`:r.status==='Submitted'?`<button class="success" data-action="approve" data-release="${r.id}">Approve first</button>`:`<span class="pill ${statusClass(r.status)}">${esc(r.status)}</span>`}</div></div></div>`:''}<div class="detail-card card"><h3>Tracks</h3><div id="detail-tracks"><div class="muted">Loading tracks…</div></div></div><div class="detail-card card"><div class="section-head"><h3>Track version history</h3><span class="muted">Previous metadata and file paths</span></div><div id="track-version-history"><p class="muted">Loading history…</p></div></div><div class="detail-card card"><h3>Track feedback</h3><p class="muted">Leave a note tied to a track and exact playback time. Add a timestamped note to a track for the label or artist to review.</p><div id="track-feedback-list"><div class="muted">Loading track feedback…</div></div><div class="comment-form track-feedback-form"><label class="field"><span>Track</span><select id="tf-track"><option value="">Loading tracks…</option></select></label><label class="field"><span>Time (seconds)</span><div class="tf-time-input"><input id="tf-seconds" type="number" min="0" max="86400" step="1" placeholder="e.g. 84"><button type="button" class="secondary" data-action="feedback-current-time" title="Use the current preview position">Use playback time</button></div></label><label class="field"><span>Feedback</span><textarea id="tf-body" rows="2" maxlength="1200" placeholder="What needs attention at this point?"></textarea></label><button class="primary" data-action="track-feedback-post" data-release="${r.id}">Add feedback</button></div></div><div class="detail-card card"><h3>Comments</h3><div id="detail-comments" class="comments"><div class="muted">Loading…</div></div><div class="comment-form"><textarea id="cm-body" rows="2" maxlength="2000" placeholder="Write a comment…"></textarea><button class="primary" data-action="post-comment">Send</button></div></div><div class="detail-card card"><h3>Earnings</h3><div id="detail-earn"></div>${isAdmin()?`<div class="invite-form earn-form"><label class="field"><span>Period</span><input id="en-period" placeholder="2026-09"></label><label class="field"><span>Streams</span><input id="en-streams" type="number" min="0" placeholder="0"></label><label class="field"><span>Amount (£)</span><input id="en-amount" type="number" step="0.01" min="0" placeholder="0.00"></label><button class="primary" data-action="add-earn">Add statement</button></div>`:''}</div>${isAdmin()?`<div class="detail-card card"><h3>Internal notes <span class="pill neutral">Label only</span></h3><div id="detail-internal" class="timeline"></div><div class="comment-form"><textarea id="in-body" rows="2" placeholder="Private note for the label team…"></textarea><button class="secondary" data-action="add-internal">Save note</button></div></div>`:''}<div class="detail-card card"><h3>Activity</h3><div id="detail-activity" class="timeline"><div class="muted">Loading…</div></div></div></section>`; }

  function supportView(){return `<section class="page fade"><div class="page-heading"><p class="eyebrow">WE’RE HERE TO HELP</p><h1>Support</h1><p class="sub">Send a message directly to the Imposed Entertainment team. Your account name and email are attached so we know who needs help.</p></div><div class="settings-card card"><div class="setting-section"><div class="setting-icon">${icon('mail',17)}</div><div><h3>Contact the label team</h3><p>Tell us what happened, what you were trying to do, and any error you saw. Please don’t include passwords or security codes.</p></div></div><div class="invite-form"><label class="field"><span>Subject</span><input id="support-subject" maxlength="100" required placeholder="e.g. Trouble uploading a release"></label><label class="field"><span>Your message</span><textarea id="support-message" maxlength="3000" rows="7" required placeholder="Describe how we can help…"></textarea></label><p class="muted">Sent as ${esc(profile.display_name||profile.full_name||session.user.user_metadata?.username||session.user.email?.split('@')[0]||'Portal user')} · ${esc(session.user.email||profile.email||'Email unavailable')}</p><button class="primary" data-action="send-support">${icon('mail',15)} Send to support</button></div></div></section>`;}
  function appearanceSettings(){const a=getAppearancePreferences();const themes=[['blood','Crimson'],['bone','Sand'],['venom','Moss'],['violet','Violet'],['ocean','Ocean'],['emerald','Emerald'],['rose','Rose'],['amber','Amber'],['midnight','Lavender'],['slate','Slate']];return `<div id="settings-appearance" class="settings-card card appearance-card"><div class="setting-section"><div class="setting-icon">${icon('palette',17)}</div><div><h3>Make it yours</h3><p>Choose a colour palette, add visual character and adjust spacing. Changes preview immediately and save to your account.</p></div></div><div class="appearance-section appearance-advanced-controls"><div class="appearance-section-head"><div><b>Workspace foundations</b><span>Choose how the entire portal behaves across devices.</span></div></div><div class="appearance-control-grid"><label class="appearance-control"><span>Colour mode</span><select data-appearance-mode aria-label="Colour mode"><option value="dark" ${a.mode==='dark'?'selected':''}>Dark</option><option value="light" ${a.mode==='light'?'selected':''}>Light</option><option value="system" ${a.mode==='system'?'selected':''}>Use device setting</option></select></label><label class="appearance-control"><span>Surface tint</span><select data-appearance-surface-tint aria-label="Surface tint"><option value="graphite" ${a.surfaceTint==='graphite'?'selected':''}>Graphite</option><option value="warm" ${a.surfaceTint==='warm'?'selected':''}>Warm charcoal</option><option value="cool" ${a.surfaceTint==='cool'?'selected':''}>Cool slate</option></select></label><label class="appearance-control"><span>Shadow intensity <output>${['Off','Subtle','Balanced','Strong'][a.shadowIntensity]||'Balanced'}</output></span><input type="range" min="0" max="3" step="1" value="${a.shadowIntensity}" data-appearance-shadow aria-label="Shadow intensity"></label><label class="appearance-control"><span>Interface text size <output>${a.fontScale}%</output></span><input type="range" min="85" max="125" step="5" value="${a.fontScale}" data-appearance-font-scale aria-label="Interface text size"></label></div></div><div class="appearance-section"><div class="appearance-section-head"><div><b>Colour themes</b><span>Choose the accent used across buttons, highlights, navigation and controls.</span></div><span class="appearance-current" id="appearance-current">${esc(themes.find(t=>t[0]===a.theme)?.[1]||'Violet')}</span></div><div class="theme-grid">${themes.map(([key,label])=>`<button type="button" class="theme-option ${a.theme===key?'selected':''}" data-theme-preset="${key}" aria-pressed="${a.theme===key}"><span class="theme-swatch theme-${key}"><i></i><i></i><i></i></span><span>${label}</span></button>`).join('')}</div><label class="appearance-custom"><span><b>Custom accent</b><small>Pick your own colour</small></span><input type="color" value="${esc(a.accent)}" data-appearance-accent aria-label="Custom accent colour"></label></div><div class="appearance-section"><div class="appearance-section-head"><div><b>Interface style</b><span>Choose how much visual detail you want.</span></div></div><div class="appearance-choice-grid"><label class="appearance-choice"><input type="radio" name="appearance-style" value="vivid" data-appearance-style ${a.style==='vivid'?'checked':''}><span class="choice-preview preview-vivid"><i></i><i></i><i></i></span><b>Vivid</b><small>Bold colour, richer panels and stronger contrast</small></label><label class="appearance-choice"><input type="radio" name="appearance-style" value="classic" data-appearance-style ${a.style==='classic'?'checked':''}><span class="choice-preview preview-classic"><i></i><i></i><i></i></span><b>Classic</b><small>Structured cards and a more traditional workspace</small></label><label class="appearance-choice"><input type="radio" name="appearance-style" value="minimal" data-appearance-style ${a.style==='minimal'?'checked':''}><span class="choice-preview preview-minimal"><i></i><i></i><i></i></span><b>Minimal</b><small>Quieter surfaces with fewer visual effects</small></label></div></div><div class="appearance-section"><div class="appearance-section-head"><div><b>Spacing</b><span>Make lists and controls feel more compact or more open.</span></div></div><div class="density-options"><label><input type="radio" name="appearance-density" value="compact" data-appearance-density ${a.density==='compact'?'checked':''}><span>Compact</span></label><label><input type="radio" name="appearance-density" value="comfortable" data-appearance-density ${a.density==='comfortable'?'checked':''}><span>Comfortable</span></label><label><input type="radio" name="appearance-density" value="spacious" data-appearance-density ${a.density==='spacious'?'checked':''}><span>Spacious</span></label></div></div><div class="appearance-section"><div class="appearance-section-head"><div><b>Overview banner</b><span>Optional artwork or a solid colour above your page content. The page automatically moves up when the banner is hidden.</span></div></div><label class="banner-toggle-row"><span><b>Show overview banner</b><small>Turn it off any time without losing your chosen design.</small></span><input type="checkbox" data-banner-enabled ${a.bannerEnabled===true?"checked":""}></label><div class="banner-picker"><div class="banner-preview" aria-hidden="true"></div><label class="secondary banner-upload">Choose image<input type="file" accept="image/jpeg,image/png,image/webp" data-banner-file hidden></label><label class="banner-colour-label">Banner colour<input type="color" value="${esc(a.bannerColor||a.accent)}" data-banner-color aria-label="Overview banner colour"></label><button type="button" class="secondary" data-banner-clear>Clear design</button></div><p class="banner-state-note" role="status" aria-live="polite">${a.bannerEnabled===true&&(a.banner||a.bannerColor)? "Banner is on.":"Banner is hidden until you choose a colour or image and switch it on."}</p></div><div class="appearance-section"><div class="appearance-section-head"><div><b>Typeface</b><span>Sets the voice of headings across the portal.</span></div></div><div class="font-grid">${[['poster','Poster','Bebas'],['blackletter','Blackletter','Gothic'],['typewriter','Typewriter','Case file'],['occult','Occult','Serif'],['clean','Clean','Modern']].map(([k,l,s2])=>`<label class="font-option font-${k}"><input type="radio" name="appearance-font" value="${k}" data-appearance-font ${a.font===k?'checked':''}><span class="font-sample">Aa</span><b>${l}</b><small>${s2}</small></label>`).join('')}</div></div><div class="appearance-section"><div class="appearance-section-head"><div><b>Card style</b><span>How panels and cards look.</span></div></div><div class="font-grid">${[['slab','Slab','Hard edge, offset shadow'],['scar','Scar','Notched corners'],['glass','Glass','Frosted, soft'],['ash','Ash','Flat, gritty']].map(([k,l,s2])=>`<label class="font-option"><input type="radio" name="appearance-cards" value="${k}" data-appearance-cards ${a.cards===k?'checked':''}><span class="card-sample card-sample-${k}"></span><b>${l}</b><small>${s2}</small></label>`).join('')}</div></div><div class="appearance-section"><div class="appearance-section-head"><div><b>Atmosphere</b><span>Film grain and corner roundness.</span></div></div><label class="appearance-range"><span>Grain <output>${a.grain}</output></span><input type="range" min="0" max="100" value="${a.grain}" data-appearance-grain aria-label="Film grain"></label><label class="appearance-range"><span>Corner roundness <output>${a.radius}</output></span><input type="range" min="0" max="24" value="${a.radius}" data-appearance-radius aria-label="Corner roundness"></label></div><div class="appearance-section dashboard-layout-settings"><div class="appearance-section-head"><div><b>Dashboard layout</b><span>Choose which sections appear on your overview. Use Customise layout on the overview to drag widgets, resize them and change their shape.</span></div></div><div class="dashboard-widget-grid">${[['metrics','Summary metrics'],['tasks','Tasks & goals'],['announcements','Label announcements'],['upcoming','Upcoming releases'],['activity','Recent activity'],['catalogue','Release catalogue']].map(([key,label])=>`<label class="dashboard-widget-option"><input type="checkbox" data-dashboard-widget="${key}" ${a.dashboard?.[key]!==false?'checked':''}><span>${esc(label)}</span></label>`).join('')}</div></div><div class="appearance-footer"><span id="appearance-save-status" role="status">Your current preferences are applied.</span><button type="button" class="secondary" data-action="reset-appearance">Reset appearance</button></div></div>`;}
  function settings(){return `<section class="page fade"><div class="page-heading"><p class="eyebrow">ACCOUNT</p><h1>Settings</h1><p class="sub">Manage your appearance, language, account and privacy in one place.</p></div><nav class="settings-quicknav" aria-label="Settings sections"><button type="button" data-settings-section="settings-appearance">Appearance</button><button type="button" data-settings-section="settings-language">Language</button><button type="button" data-settings-section="settings-account">Account</button><button type="button" data-settings-section="settings-notifications">Notifications</button><button type="button" data-settings-section="settings-security">Security</button><button type="button" data-settings-section="settings-data">Your data</button></nav>${appearanceSettings()}<div id="settings-language" class="settings-card card"><div class="setting-section"><div class="setting-icon">${icon('globe',17)}</div><div><h3>Language preference</h3><p>Choose the language used for portal navigation and supported interface labels.</p></div></div><div class="setting-row"><div><b>Language</b><span>Applies to menus and labels. It does not change your release information.</span></div></div><div class="language-choice-grid" role="group" aria-label="Choose portal language">${[['en','🇬🇧','English','English'],['es','🇪🇸','Español','Spanish'],['fr','🇫🇷','Français','French'],['de','🇩🇪','Deutsch','German'],['pt','🇵🇹','Português','Portuguese'],['pl','🇵🇱','Polski','Polish']].map(([code,flag,label,english])=>`<button type="button" class="language-choice" data-language-choice="${code}" aria-pressed="${(window.IE_I18N?.language||'en')===code}" aria-label="Switch language to ${english}"><span class="language-choice-flag" aria-hidden="true">${flag}</span><span class="language-choice-name">${label}</span><span class="language-choice-check" aria-hidden="true">✓</span></button>`).join('')}</div><p class="language-choice-note" role="status" aria-live="polite">Your language is saved on this device and, when signed in, synced to your account.</p></div><div id="settings-account" class="settings-card card"><div class="setting-section"><div class="setting-icon">${icon('users',17)}</div><div><h3>Profile</h3><p>Shown to the label team.</p></div></div>${isAdmin()?`<div class="setting-row"><div><b>Label identity</b><span>${esc(profile.display_name||'')}</span></div><span class="pill neutral">Label account</span></div>`:`<div class="setting-row"><div><b>Name</b><span>${esc(profile.display_name||'')}</span></div><span class="pill neutral">Set by the label</span></div>`}<div class="setting-row"><div><b>Email</b><span>${esc(profile.email||session.user.email||'')}</span></div></div><div class="setting-row"><div><b>Role</b><span>${isAdmin()?'Label team':'Artist'}</span></div></div>${isAdmin()?`<div class="setting-row"><div><b>Workspace management</b><span>Manage artists, invitations and release reviews from your label workspace.</span></div><div class="row-actions"><button class="secondary" data-action="roster">Artist roster</button><button class="primary" data-action="pipeline">Release pipeline</button></div></div>`:`<div class="setting-row"><div><b>Public page</b><span>Photo, banner, bio, links, colour and contact details</span></div><div class="row-actions"><button class="secondary" data-pf="my-page">View</button><button class="primary" data-pf="edit-profile">Edit profile</button></div></div><div class="setting-row"><div><b>Profile completeness</b><span>Help the label and other artists recognise you.</span><div class="bar"><i style="width:${profileCompletion(profile)}%"></i></div><small>${profileCompletion(profile)}% complete</small></div></div>`}</div></div><div id="settings-notifications" class="settings-card card"><div class="setting-section"><div class="setting-icon">${icon('bell',17)}</div><div><h3>Notification preferences</h3><p>Choose which notification categories and dashboard announcements appear for this account.</p></div></div><div class="setting-row"><div><b>Release updates</b><span>Status changes and review feedback</span></div><input type="checkbox" aria-label="Show release update notifications" data-pref="release_updates" ${(profile.notification_preferences||{}).release_updates!==false?'checked':''}></div><div class="setting-row"><div><b>Band invitations</b><span>Invites to join a band</span></div><input type="checkbox" aria-label="Show band invitation notifications" data-pref="band_invites" ${((profile.notification_preferences||{}).band_invites)!==false?'checked':''}></div><div class="setting-row"><div><b>Label announcements</b><span>Label announcement inbox notifications and email</span></div><input type="checkbox" aria-label="Show dashboard announcements" data-pref="announcements" ${((profile.notification_preferences||{}).announcements)!==false?'checked':''}></div><div class="setting-row"><div><b>Unread badge</b><span>Show the unread count in navigation</span></div><input type="checkbox" aria-label="Show unread notification badge" data-pref="unread_badge" ${((profile.notification_preferences||{}).unread_badge)!==false?'checked':''}></div><p class="muted" style="padding:0 18px 16px">The Label announcements setting controls both inbox notifications and announcement emails. Turn it off to opt out of both.</p></div>${(()=>{const ids=session.user.identities||[];const providers=[{key:'google',label:'Google'},{key:'x',legacyKey:'twitter',label:'X'},{key:'discord',label:'Discord'}];const em=ids.some(i=>i.provider==='email');return `<div id="settings-security" class="settings-card card"><div class="setting-section"><div class="setting-icon">${icon('shield',17)}</div><div><h3>Sign-in methods</h3><p>Link another provider to this invited account. Linking does not create a new account.</p></div></div>${providers.map(p=>{const ident=ids.find(i=>i.provider===p.key||(p.legacyKey&&i.provider===p.legacyKey));return `<div class="setting-row"><div><b>${p.label}</b><span>${ident?esc((ident.identity_data&&(ident.identity_data.email||ident.identity_data.name||ident.identity_data.preferred_username))||'Connected account'):'Not linked to this account'}</span></div><div class="row-actions">${ident?`<span class="pill green">Linked</span><button class="secondary mini" data-action="unlink-identity" data-provider="${ident.provider}" data-identity-id="${esc(ident.identity_id||ident.id||'')}">Unlink</button>`:`<span class="pill neutral">Not linked</span><button class="secondary mini provider-link-btn" data-action="link-provider" data-provider="${p.key}">Link ${p.label}</button>`}</div></div>`;}).join('')}<div class="setting-row"><div><b>Email &amp; password</b><span>${esc(session.user.email||'')}</span></div><span class="pill ${em?'green':'neutral'}">${em?'Available':'Not set'}</span></div><p class="muted settings-security-note">Keep at least two sign-in methods linked before removing one. Provider availability depends on the Supabase Auth provider settings.</p></div>`;})()}<div class="settings-card card"><div class="setting-section"><div class="setting-icon">${icon('upload',17)}</div><div><h3>Storage</h3><p>Your uploads count toward a fixed allowance.</p></div></div><div class="setting-row"><div id="st-usage" style="flex:1"><span>Calculating…</span></div></div></div><div id="settings-data" class="settings-card card"><div class="setting-section"><div class="setting-icon">${icon('download',17)}</div><div><h3>Your data</h3><p>Download a portable JSON copy of your profile and the personal workspace data currently available to your account.</p></div></div><div class="setting-row"><div><b>Personal data export</b><span>Includes your profile, owned releases, related tasks, visible notifications and band memberships. Audio and private files are excluded.</span></div><button class="secondary" data-action="export-account-data">Export my data</button></div></div><div class="settings-card card"><div class="setting-section"><div class="setting-icon">${icon('activity',17)}</div><div><h3>Compatibility &amp; connection</h3><p>Check whether this browser supports the portal's main features and export a small diagnostic report for troubleshooting.</p></div></div><div class="setting-row"><div><b>Browser diagnostics</b><span>Includes app version, browser capabilities, connectivity and viewport size. It does not include your email, release data or authentication tokens.</span></div><button class="secondary" data-action="download-diagnostics">Download diagnostics</button></div></div><div class="settings-card card"><div class="setting-section"><div class="setting-icon">${icon('shield',17)}</div><div><h3>Session</h3><p>Sign out from this device.</p></div></div><div class="setting-row"><div><b>Signed-in account</b><span>${esc(session.user.email||"Your account")}</span></div><button class="danger-btn" data-action="logout">${icon('logout',14)} Sign out</button></div></div></section>`; }
  function inviteUrl(i){return location.origin+location.pathname+'?invite='+encodeURIComponent(i.code);}
  function invitePanel(){
    const rows=invites.map(i=>{const st=i.status==='Pending'&&i.expires_at&&new Date(i.expires_at)<new Date()?'Expired':i.status;const open=st==='Pending';const account=users.find(u=>String(u.email||'').toLowerCase()===String(i.email||'').toLowerCase());
      return `<article class="roster-row invite-row ${account?'invite-row-linked':''}" ${account&&st==='Accepted'?`data-pf="open-profile" data-id="${esc(account.id)}" role="button" tabindex="0" aria-label="Manage profile for ${esc(account.display_name||i.email)}"`:''}><div class="roster-avatar">${icon('mail',16)}</div><div class="release-info"><strong>${esc(i.artist_name||account?.display_name||i.email)}</strong><span>${esc(i.email)} · invited ${dateFmt(i.created_at?.slice(0,10))}</span></div><span class="pill ${i.role==='label_admin'?'amber':'neutral'}">${i.role==='label_admin'?'Label member':'Artist'}</span><span class="pill ${st==='Accepted'?'green':st==='Pending'?'blue':'neutral'}">${esc(st)}</span><div class="row-actions invite-row-actions">${account&&st!=='Accepted'?`<button class="secondary mini" data-pf="open-profile" data-id="${esc(account.id)}">Manage profile</button>`:''}${open?`<a class="secondary mini" href="mailto:${esc(i.email)}?subject=${encodeURIComponent('Your Imposed Entertainment invite')}&body=${encodeURIComponent('You have been invited to the Imposed Entertainment artist portal.\n\nCreate your account here: '+inviteUrl(i))}">Email</a><button class="secondary mini" data-action="copy-invite" data-code="${esc(i.code)}">Copy link</button><button class="danger-btn mini" data-action="revoke-invite" data-id="${esc(i.id)}">Revoke</button>`:''}</div></article>`;}).join('');
    return `<div class="card invite-card"><div class="panel-title"><div><h2>Invite someone</h2><p>Pick their role, then send them the link. Accounts are invite-only.</p></div></div><div class="seg"><button class="${inviteRole==='artist'?'on':''}" data-action="invite-role" data-r="artist">Artist</button><button class="${inviteRole==='label_admin'?'on':''}" data-action="invite-role" data-r="label_admin">Label member</button></div><div class="invite-form"><label class="field"><span>${inviteRole==='artist'?'Artist name':'Full name'}</span><input id="inv-name" placeholder="Artist or act name"></label><label class="field"><span>Email</span><input id="inv-email" type="email" placeholder="artist@example.com"></label><button class="primary" data-action="create-invite">${icon('plus',15)} Create invite</button></div>${rows?`<div class="roster-list">${rows}</div>`:''}</div>`;
  }
  let rosterQ='all', rosterSearch='';
  function roster(){if(!isAdmin())return dashboard();const rosterUsers=users.filter(u=>(!rosterSearch||`${u.display_name||''} ${u.email||''}`.toLowerCase().includes(rosterSearch.toLowerCase()))&&(rosterQ==='all'||(rosterQ==='artists'&&!isAdminRole(u.role))||(rosterQ==='label'&&isAdminRole(u.role))));return `<section class="page fade"><div class="page-heading"><p class="eyebrow">LABEL</p><h1>Roster</h1><p class="sub">All artist and label-member accounts, plus the invites you have sent.</p></div>${invitePanel()}<div class="roster-tools"><input id="roster-search" value="${esc(rosterSearch)}" placeholder="Search artists and emails…" aria-label="Search roster"><div class="chips">${[['all','Everyone'],['artists','Artists'],['label','Label team']].map(([v,l])=>`<button class="chip ${rosterQ===v?'active':''}" data-action="roster-filter" data-filter="${v}">${l}</button>`).join('')}</div></div><div class="roster-list card">${rosterUsers.map(u=>`<article class="roster-row account-row"><button type="button" class="roster-avatar roster-avatar-profile" data-pf="open-profile" data-id="${esc(u.id)}" aria-label="Open ${esc(u.display_name||u.email||'artist')} profile">${avatarHtml(u,48)}</button><div class="release-info"><button type="button" class="roster-profile-name" data-pf="open-profile" data-id="${esc(u.id)}">${esc(u.display_name||'Unnamed artist')}</button><span>${esc(u.email||'')} · joined ${dateFmt(u.created_at?.slice(0,10))}</span></div><span class="pill ${isAdminRole(u.role)?'green':'neutral'}">${isAdminRole(u.role)?'Label member':'Artist'}</span><div class="row-actions account-row-actions"><button class="secondary mini" data-pf="open-profile" data-id="${esc(u.id)}">View profile</button>${u.id!==profile.id?`<button class="secondary mini" data-action="toggle-role" data-user="${esc(u.id)}" data-role="${esc(u.role)}">${isAdminRole(u.role)?'Remove label access':'Make label member'}</button>`:''}</div></article>`).join('')||`<div class="empty"><h3>No matching members</h3><p>Invited artists and label members appear here after they accept an invite.</p></div>`}</div></section>`; }
